class MessageProcessor(ABC):
    """Abstract interface callers depend on for communicating with a bot model.

    Concrete behaviour lives in :class:`BaseMessageProcessor` (shared) and its
    engine-specific subclasses :class:`CalmMessageProcessor` and
    :class:`rasa.mantle.processor.MantleMessageProcessor`. External code holds a
    ``MessageProcessor``-typed reference and never branches on the engine version.
    """

    # Externally-read attributes (set during construction in BaseMessageProcessor).
    model_metadata: ModelMetadata
    model_filename: str
    model_path: Path
    domain: Domain
    engine_version: str
    is_calm_assistant: bool

    @property
    @abstractmethod
    def session_config(self) -> SessionConfig:
        """Conversation session configuration for the active engine.

        Engine seam so shared session/tracker code (and the A2A server) never
        reads ``self.domain.session_config`` directly. CALM v1 sources it from
        the domain; Mantle sources it from ``agent.yml`` (see ENG-2875).
        """
        ...

    @abstractmethod
    async def handle_message(
        self, message: UserMessage
    ) -> Optional[List[Dict[str, Any]]]: ...

    async def replay_message(
        self, tracker: DialogueStateTracker, message: UserMessage
    ) -> None:
        """Replay a previously processed message when supported by the processor."""
        return None

    def voice_silence_timeout(self) -> Optional[float]:
        """Return an agent-wide silence timeout in seconds, when this engine has one.

        CALM keeps that timeout on the voice channel. Mantle overrides this
        with ``voice.silence_timeout`` from ``agent.yml``.
        """
        return None

    @staticmethod
    def is_duplicate_message(
        tracker: DialogueStateTracker, message: UserMessage
    ) -> bool:
        """Return whether a message was already processed by the processor."""
        return False

    @abstractmethod
    async def handle_voice_conversation(
        self,
        input_queue: "ConversationQueue[InputEvent]",
        output_channel: OutputChannel,
        sender_id: str,
        channel_controller: "Optional[ChannelController]" = None,
    ) -> None: ...

    @abstractmethod
    async def parse_message(
        self,
        message: UserMessage,
        tracker: Optional[DialogueStateTracker] = None,
        only_output_properties: bool = True,
    ) -> Dict[str, Any]: ...

    @abstractmethod
    async def get_tracker(
        self, conversation_id: str, user_id: Optional[str] = None
    ) -> DialogueStateTracker: ...

    @abstractmethod
    async def fetch_tracker_with_initial_session(
        self,
        sender_id: str,
        output_channel: Optional[OutputChannel] = None,
        metadata: Optional[Dict] = None,
    ) -> DialogueStateTracker: ...

    @abstractmethod
    async def fetch_tracker_and_update_session(
        self,
        sender_id: str,
        output_channel: Optional[OutputChannel] = None,
        metadata: Optional[Dict] = None,
    ) -> DialogueStateTracker: ...

    @abstractmethod
    async def fetch_full_tracker_with_initial_session(
        self,
        conversation_id: str,
        output_channel: Optional[OutputChannel] = None,
        metadata: Optional[Dict] = None,
    ) -> DialogueStateTracker: ...

    @abstractmethod
    async def get_trackers_for_all_conversation_sessions(
        self, conversation_id: str
    ) -> List[DialogueStateTracker]: ...

    @abstractmethod
    async def save_tracker(self, tracker: DialogueStateTracker) -> None: ...

    @abstractmethod
    async def record_event_on_tracker(
        self, tracker: DialogueStateTracker, event: Event
    ) -> None: ...

    @abstractmethod
    async def log_message(
        self,
        message: UserMessage,
        should_save_tracker: bool = True,
    ) -> DialogueStateTracker: ...

    @abstractmethod
    def trigger_anonymization(self, tracker: DialogueStateTracker) -> None: ...

    @abstractmethod
    def install_privacy(self) -> None: ...

    @abstractmethod
    def cancel_background_tasks(self, sender_id: str) -> bool: ...

    @abstractmethod
    def register_cancellation_token(
        self, sender_id: str, token: "CancellationToken"
    ) -> None: ...

    @abstractmethod
    def unregister_cancellation_token(self, sender_id: str) -> None: ...

    @abstractmethod
    def get_cancellation_token(
        self, sender_id: str
    ) -> Optional["CancellationToken"]: ...

    @abstractmethod
    async def handle_session_timeout(
        self,
        sender_id: str,
        session_id: Optional[str],
        scheduled_time: Optional[float] = None,
    ) -> None: ...

    @abstractmethod
    async def deliver_pending_async_update(
        self,
        conversation_id: str,
        output_channel: OutputChannel,
        input_channel: Optional[str] = None,
    ) -> bool: ...

    @abstractmethod
    async def get_flows(self) -> FlowsList: ...

    async def inspector_data(self) -> Dict[str, Any]:
        """Static project data served on the inspector's ``GET /data``.

        The base payload carries the domain, the flow definitions, the
        assistant id, and an explicit ``engine`` field. This CALM v1 path
        declares ``engine="calm"``; the Mantle path overrides it to
        ``"mantle"``.
        """
        from rasa.shared.core.flows.yaml_flows_io import get_flows_as_json

        flows = await self.get_flows()
        assistant_id = getattr(self.model_metadata, "assistant_id", None)
        return {
            "domain": self.domain.as_dict(),
            "flows": get_flows_as_json(flows),
            "assistant_id": assistant_id,
            "engine": "calm",
        }

    def inspector_skill_state(
        self, tracker: DialogueStateTracker
    ) -> Optional[Dict[str, Any]]:
        """Per-tracker skill state for the development inspector.

        Engines without a skill catalog return ``None``; the inspector's
        tracker payloads then omit the ``skill_state`` key.
        """
        return None

    @abstractmethod
    async def prepare_subagents(self, sub_agents: "AvailableAgents") -> None: ...

    async def prepare_runtime_integrations(self) -> None:
        """Connect process-lifetime integrations after the model is loaded.

        CALM has none. Mantle connects MCP servers referenced by skills.
        """
        return None

    async def close_runtime_integrations(self) -> None:
        """Release process-lifetime integrations. Safe to call more than once."""
        return None

    @abstractmethod
    async def run_command_processor(
        self, tracker: DialogueStateTracker
    ) -> DialogueStateTracker: ...

    @abstractmethod
    async def run_action_extract_slots(
        self,
        output_channel: OutputChannel,
        tracker: DialogueStateTracker,
    ) -> DialogueStateTracker: ...

    @abstractmethod
    async def run_prediction_loop(
        self,
        output_channel: OutputChannel,
        tracker: DialogueStateTracker,
        cancellation_token: Optional["CancellationToken"] = None,
    ) -> None: ...

    @abstractmethod
    async def process_tracker(
        self,
        output_channel: OutputChannel,
        tracker: DialogueStateTracker,
        cancellation_token: Optional["CancellationToken"] = None,
    ) -> None: ...

    @abstractmethod
    async def predict_next_with_tracker_if_should(
        self,
        tracker: DialogueStateTracker,
        output_channel: Optional[OutputChannel] = None,
        cancellation_token: Optional["CancellationToken"] = None,
    ) -> Tuple[rasa.core.actions.action.Action, PolicyPrediction]: ...

    @abstractmethod
    async def predict_next_with_tracker(
        self,
        tracker: DialogueStateTracker,
        verbosity: EventVerbosity = EventVerbosity.AFTER_RESTART,
    ) -> Optional[Dict[str, Any]]: ...

    @abstractmethod
    async def predict_next_for_sender_id(
        self, sender_id: str
    ) -> Optional[Dict[str, Any]]: ...

    @abstractmethod
    async def execute_action(
        self,
        sender_id: str,
        action_name: str,
        output_channel: OutputChannel,
        nlg: NaturalLanguageGenerator,
        prediction: PolicyPrediction,
    ) -> Optional[DialogueStateTracker]: ...

    @abstractmethod
    async def execute_side_effects(
        self,
        events: List[Event],
        tracker: DialogueStateTracker,
        output_channel: Optional[OutputChannel],
    ) -> None: ...

    @abstractmethod
    async def trigger_external_user_uttered(
        self,
        intent_name: str,
        entities: Optional[Union[List[Dict[str, Any]], Dict[str, str]]],
        tracker: DialogueStateTracker,
        output_channel: OutputChannel,
    ) -> None: ...

    @abstractmethod
    async def handle_reminder(
        self,
        reminder_event: ReminderScheduled,
        sender_id: str,
        output_channel: OutputChannel,
    ) -> None: ...


class BaseMessageProcessor(MessageProcessor):
    """Engine-agnostic shared functionality for every message processor.

    Concrete for all shared behaviour, but still abstract: it leaves the
    engine-divergent public methods (declared on :class:`MessageProcessor`)
    unimplemented and additionally declares two internal seams
    (``_run_engine_turn``, ``_parse_message_for_engine``) that its shared
    template methods call. The CALM v1 and Mantle processors fill those in.
    """

    @abstractmethod
    async def _run_engine_turn(
        self,
        message: UserMessage,
        tracker: DialogueStateTracker,
    ) -> DialogueStateTracker:
        """Run one dialogue-engine turn and return the (possibly updated) tracker."""
        ...

    @abstractmethod
    async def _parse_message_for_engine(
        self,
        message: UserMessage,
        tracker: Optional[DialogueStateTracker] = None,
        only_output_properties: bool = True,
    ) -> Dict[str, Any]:
        """Parse a user message into parse_data for the active engine version."""
        ...

    @abstractmethod
    async def _start_new_session(
        self,
        tracker: DialogueStateTracker,
        output_channel: OutputChannel,
        metadata: Optional[Dict] = None,
    ) -> None:
        """Initialise a new conversation session on the tracker.

        Engine seam invoked by ``_update_tracker_session``. CALM v1 runs
        ``action_session_start`` through the action machinery; Mantle emits the
        session-start events and activates its session-start skill directly.
        """
        ...

    @abstractmethod
    async def _resolve_turn_flows(self) -> Optional[FlowsList]:
        """Return the flows for the current turn, or ``None`` if not applicable.

        Engine seam used by ``handle_message`` and ``log_message``. CALM v1
        returns the model's flows for CALM assistants; Mantle has no separate
        flows list and returns ``None``.
        """
        ...

    @abstractmethod
    async def _purge_stale_frames_for_turn(self, tracker: DialogueStateTracker) -> None:
        """Remove stack frames that reference flows no longer valid in the model.

        Engine seam used before the turn runs. CALM v1 purges stale user-flow
        frames; Mantle is a no-op.
        """
        ...

    @abstractmethod
    def _cleanup_on_session_timeout(self, tracker: DialogueStateTracker) -> None:
        """Perform engine-specific cleanup when a session times out.

        Engine seam used by ``handle_session_timeout``. CALM v1 expires stale
        processing-agent frames; Mantle is a no-op.
        """
        ...

    @abstractmethod
    def _engine_prefill_commands(
        self, message_metadata: Dict[str, Any], parse_data: Dict[str, Any]
    ) -> List[Dict[str, Any]]:
        """Return engine-specific commands to prefill onto the incoming message.

        Engine seam used by ``_handle_message_with_tracker``. CALM v1 derives
        A2A-client set-slot commands; Mantle returns an empty list.
        """
        ...

    @abstractmethod
    def _log_turn_slots(self, tracker: DialogueStateTracker) -> None:
        """Log the slots/memory set on the tracker for the current turn.

        Engine seam used by ``_handle_message_with_tracker``. CALM v1 logs the
        domain slots; Mantle is a no-op for now (memory logging is a follow-up).
        """
        ...

    # Per-turn timing markers for the CALM v1 path. ``time_turn_start`` is
    # stamped in the shared ``handle_message`` template; ``time_command_processor``
    # is stamped only on the CALM v1 prediction path. Both are read by the v1
    # ``_compute_execution_times_ms``. Mantle does not use these — it reads its
    # turn-start marker from the per-turn ``MessageTurnContext`` instead, which is
    # concurrency-safe.
    # TODO(ENG-2867): the v1 markers still live on the shared processor instance
    # and are not concurrency-safe — move them to a per-turn timing context too.
    time_turn_start: float
    time_command_processor: float

    def __init__(
        self,
        model_path: Union[str, Path],
        tracker_store: rasa.core.tracker_stores.tracker_store.TrackerStore,
        lock_store: LockStore,
        generator: NaturalLanguageGenerator,
        action_endpoint: Optional[EndpointConfig] = None,
        max_number_of_predictions: int = MAX_NUMBER_OF_PREDICTIONS,
        max_number_of_predictions_calm: int = MAX_NUMBER_OF_PREDICTIONS_CALM,
        on_circuit_break: Optional[LambdaType] = None,
        http_interpreter: Optional[RasaNLUHttpInterpreter] = None,
        endpoints: Optional["AvailableEndpoints"] = None,
        privacy_manager: Optional["BackgroundPrivacyManager"] = None,
        timer_manager: Optional["SessionTimerManager"] = None,
        model_archive: Optional[Union[str, Path]] = None,
    ) -> None:
        """Initializes a `MessageProcessor`.

        ``model_archive``, when provided, is the concrete archive already resolved by
        ``create_message_processor`` — passing it avoids a second ``get_latest_model``
        lookup (and the race where the newest archive changes between the two). The
        ``model_path`` attribute still reflects the originally requested path.
        """
        self.tracker_store = tracker_store
        self.lock_store = lock_store
        self.timer_manager = timer_manager
        self.on_circuit_break = on_circuit_break
        # The graph runner is a CALM v1 / NLU construct. Base loads it (it is the
        # cheapest place to do so, given ``_load_model`` already runs here) and
        # parks it on a neutral attribute. ``CalmMessageProcessor`` reads it into
        # ``self.graph_runner``; the Mantle processor ignores it.
        # TODO(ENG-2872): don't build the v1 graph runner for Mantle — move the
        # model/graph load into CalmV1 and load only metadata (no graph) in Base.
        (
            self.model_filename,
            self.model_metadata,
            self._loaded_graph_runner,
        ) = self._load_model(model_archive if model_archive is not None else model_path)
        self.endpoints = endpoints
        # Flows are derived from the loaded model's graph and never change without
        # a full model reload, which always creates a new `MessageProcessor`
        # instance (see `Agent.load_model`) - safe to cache for this instance's
        # lifetime instead of re-dispatching the graph runner on every call.
        self._flows: Optional[FlowsList] = None

        self.engine_version = resolve_runtime_engine_version(
            self.model_metadata.engine_version
        )

        if self.model_metadata.assistant_id is None:
            rasa.shared.utils.io.raise_warning(
                f"The model metadata does not contain a value for the "
                f"'{ASSISTANT_ID_KEY}' attribute. Check that 'config.yml' "
                f"file contains a value for the '{ASSISTANT_ID_KEY}' key "
                f"and re-train the model. Failure to do so will result in "
                f"streaming events without a unique assistant identifier.",
                UserWarning,
            )

        self.model_path = Path(model_path)
        # ``self.domain`` is load-bearing for shared session/tracker code and is
        # kept in Base for now.
        # TODO(ENG-2870): make ``domain`` a CALM-v1-only property (v2 is
        # domain-less) and rework the shared callers.
        self.domain = self.model_metadata.domain

        self.privacy_manager = privacy_manager
        self._active_cancellation_tokens: Dict[str, "CancellationToken"] = {}
        self._init_engine_specific_state()
        self._prepare_privacy()

    async def _handle_voice_input_event(
        self,
        event: CompositeEvent,
        output_channel: OutputChannel,
        sender_id: str,
        input_channel: str,
    ) -> None:
        """Route one composed voice `InputEvent` inside a held conversation lock."""
        structlogger.debug(
            "processor._handle_voice_input_event.handling_event",
            sender_id=sender_id,
            event_type=type(event).__name__,
            input_channel=input_channel,
        )
        signal_event = event.to_tracker_event()
        if signal_event is not None:
            tracker = await self.get_tracker(sender_id)
            await self.record_event_on_tracker(tracker, signal_event)
            return

        if isinstance(
            event, UserTranscript
        ) and await self._should_reject_transcript_during_dtmf(sender_id):
            voice_tracing.record_transcript_rejected(reason="dtmf_audio_input_disabled")
            structlogger.info(
                "processor.voice_input.transcript_rejected_during_dtmf",
                sender_id=sender_id,
            )
            tracker = await self.get_tracker(sender_id)
            await self.record_event_on_tracker(
                tracker,
                UserInputSuppressed(
                    text=event.text,
                    modality="audio",
                    reason="dtmf_audio_input_disabled",
                    metadata=event.metadata,
                ),
            )
            return

        message = event.to_user_message(
            output_channel,
            sender_id,
            input_channel,
        )
        if message is not None:
            await output_channel.resume_response()
            # Make the turn's input anchor ambient so turn observability can measure
            # latency from the user's input, queueing included.
            # Restore the call context before entering any handle_message wrappers;
            # those wrappers create their spans before the method body runs.
            with (
                voice_tracing.voice_call_context(),
                bind_turn_input_anchor(turn_input_anchor_from_event(event)),
            ):
                await self.handle_message(message)
        else:
            structlogger.warning(
                "processor.handle_voice_conversation.unhandled_event",
                sender_id=sender_id,
                event_type=type(event).__name__,
            )

    async def _should_reject_transcript_during_dtmf(self, sender_id: str) -> bool:
        """Return whether the active DTMF collect step disables audio input."""
        active_collect = await self._resolve_active_dtmf_collect(sender_id)
        return active_collect is not None and not active_collect.allow_audio_input

    async def _resolve_active_dtmf_collect(
        self, sender_id: str
    ) -> Optional[ActiveDTMFCollect]:
        """Return the active DTMF collect configuration for this engine."""
        return None

    async def _handle_voice_barge_in(
        self, output_channel: OutputChannel, sender_id: str
    ) -> None:
        """Cancel the active engine turn and interrupt its channel response."""
        self.cancel_background_tasks(sender_id)
        await output_channel.interrupt_response()

    async def _run_voice_conversation_loop(
        self,
        interaction_event_queue: "ConversationQueue[CompositeEvent]",
        output_channel: OutputChannel,
        sender_id: str,
        event_composer: EventComposer,
    ) -> None:
        """Process composed interaction events until the voice session ends.

        Wraps each turn in ``event_composer.turn()``, so silence monitoring also
        covers turns that end with nothing to play.
        """
        from rasa.agents.core.cancellation import CancellationToken

        while True:
            event = await interaction_event_queue.get()

            structlogger.debug(
                "processor.handle_voice_conversation.event",
                sender_id=sender_id,
                event_type=type(event).__name__,
            )

            # Detect session end before acquiring the lock so the signal is never
            # lost, even if processing the events raises an exception.
            session_ended = isinstance(event, SessionEndedInteractionEvent)

            with event_composer.turn():
                # Fresh token per turn; registered before the lock so it is discoverable
                # for the full turn duration (cancellation is lock-free).
                token = CancellationToken()
                self.register_cancellation_token(sender_id, token)
                try:
                    async with self.lock_store.lock(sender_id):
                        try:
                            await self._handle_voice_input_event(
                                event,
                                output_channel,
                                sender_id,
                                interaction_event_queue.input_channel,
                            )
                        except Exception as e:
                            # TODO: Decide what the agent should say or do when a turn
                            #       fails (e.g. send a fallback response or terminate
                            #       the call gracefully).

                            structlogger.error(
                                "processor.handle_voice_conversation.turn_failed",
                                event_info=(
                                    "An exception occurred processing a voice turn."
                                ),
                                sender_id=sender_id,
                                error=repr(e),
                            )
                            raise
                finally:
                    self.unregister_cancellation_token(sender_id)

            if session_ended:
                structlogger.info(
                    "processor.handle_voice_conversation.session_ended",
                    sender_id=sender_id,
                )
                return

    def _init_engine_specific_state(self) -> None:
        """Initialise engine-version-specific construction state.

        The base (CALM v1 / NLU) processor needs no additional state. The Mantle
        processor overrides this to resolve its static model bootstrap from the
        archive. Called once at the end of ``__init__``.
        """
        return None

    def _prepare_privacy(self) -> None:
        """Validate privacy settings for this model while it is being built.

        Raising here fails the model load before the processor is installed.
        CALM v1 privacy comes from ``endpoints.yml`` and is already on the
        shared privacy manager, so only the domain is checked.
        """
        if self.privacy_manager is not None:
            self.privacy_manager.validate_sensitive_slots_in_domain(self.domain)

    def install_privacy(self) -> None:
        """Apply this model's privacy settings to the shared privacy manager.

        Called when the processor starts serving traffic. CALM v1 settings do
        not change across models, so there is nothing to apply.
        """
        return None

    def register_cancellation_token(
        self, sender_id: str, token: "CancellationToken"
    ) -> None:
        """Register a cancellation token for a conversation turn."""
        self._active_cancellation_tokens[sender_id] = token

    def unregister_cancellation_token(self, sender_id: str) -> None:
        """Remove a cancellation token after the turn completes."""
        self._active_cancellation_tokens.pop(sender_id, None)

    def get_cancellation_token(self, sender_id: str) -> Optional["CancellationToken"]:
        """Return the active cancellation token for a sender, if any."""
        return self._active_cancellation_tokens.get(sender_id)

    def cancel_background_tasks(self, sender_id: str) -> bool:
        """Signal cancellation for in-flight background tasks.

        Lock-free: safe to call from the session timer or any channel
        disconnect handler without holding the conversation lock.

        Returns:
            ``True`` if a token was found and signaled, ``False`` otherwise.
        """
        if token := self._active_cancellation_tokens.get(sender_id):
            structlogger.debug(
                "processor.cancel_background_tasks",
                event_info=f"Cancelling background tasks for sender_id '{sender_id}'.",
            )
            token.cancel()
            return True

        structlogger.debug(
            "processor.cancel_background_tasks.no_token_found",
            event_info=f"No cancellation token found for sender_id '{sender_id}'.",
        )
        return False

    @staticmethod
    def _resolve_model_archive(model_path: Union[str, Path]) -> str:
        """Resolve a model path (file or directory) to a concrete archive path."""
        try:
            if os.path.isfile(model_path):
                return str(model_path)
            model_file_path = get_latest_model(model_path)
            if not model_file_path:
                raise ModelNotFound(f"No model found at path '{model_path}'.")
            return model_file_path
        except TypeError:
            raise ModelNotFound(f"Model {model_path} can not be loaded.")

    @staticmethod
    def _read_engine_version(model_path: Union[str, Path]) -> str:
        """Read the engine version from a model archive without building the graph.

        This is a cheap, metadata-only read used by ``create_message_processor`` to
        pick the right processor subtype once, before the (expensive) graph runner
        is built in ``_load_model``.
        """
        model_tar = BaseMessageProcessor._resolve_model_archive(model_path)
        try:
            metadata = LocalModelStorage.metadata_from_archive(model_tar)
        except tarfile.ReadError:
            # Mirror ``_load_model``: a path that exists but is not a valid model
            # archive (e.g. a stray YAML file) surfaces as ``ModelNotFound``.
            raise ModelNotFound(f"Model {model_path} can not be loaded.")
        return resolve_runtime_engine_version(metadata.engine_version)

    @staticmethod
    def _load_model(
        model_path: Union[str, Path],
    ) -> Tuple[str, ModelMetadata, GraphRunner]:
        """Unpacks a model from a given path using the graph model loader."""
        model_tar = BaseMessageProcessor._resolve_model_archive(model_path)

        structlogger.info(
            "rasa.core.processor.load_model",
            event_info="Loading model.",
            model_path=model_tar,
        )
        with TempDirectoryPath(get_temp_dir_name()) as temporary_directory:
            try:
                metadata, runner = loader.load_predict_graph_runner(
                    Path(temporary_directory),
                    Path(model_tar),
                    LocalModelStorage,
                    DaskGraphRunner,
                )
                return os.path.basename(model_tar), metadata, runner
            except tarfile.ReadError:
                raise ModelNotFound(f"Model {model_path} can not be loaded.")

    @staticmethod
    def is_duplicate_message(
        tracker: DialogueStateTracker, message: UserMessage
    ) -> bool:
        """Check whether a message with the same id was already processed.

        Channels that receive messages over retried webhooks (e.g. AudioCodes,
        which resends an activity when the agent has not responded in time)
        set ``message_id`` on the ``UserMessage``. A retry then carries the
        same id as the already-processed message and is dropped here instead
        of triggering a second bot turn.

        Only the ``DUPLICATE_MESSAGE_LOOKBACK`` most recent user messages are
        compared, so the check does not scale with conversation length.
        """
        if not message.message_id:
            return False

        checked = 0
        for event in reversed(tracker.events):
            if isinstance(event, UserUttered):
                if event.message_id == message.message_id:
                    return True
                checked += 1
                if checked >= DUPLICATE_MESSAGE_LOOKBACK:
                    break
        return False

    @staticmethod
    def _events_for_message_id(
        tracker: DialogueStateTracker, message_id: Optional[str]
    ) -> List[Event]:
        """Return events from a message's turn, excluding later turns."""
        if not message_id:
            return []

        events = list(tracker.events)
        for index in range(len(events) - 1, -1, -1):
            event = events[index]
            if isinstance(event, UserUttered) and event.message_id == message_id:
                turn_events: List[Event] = []
                for following_event in events[index + 1 :]:
                    if isinstance(following_event, UserUttered):
                        break
                    turn_events.append(following_event)
                return turn_events

        return []

    async def replay_message(
        self, tracker: DialogueStateTracker, message: UserMessage
    ) -> None:
        """Replay persisted bot responses without running the turn again."""
        events = self._events_for_message_id(tracker, message.message_id)
        if not events:
            return

        message.output_channel.attach_tracker_state(tracker)
        for event in events:
            if isinstance(event, BotUttered):
                await self._send_bot_messages([event], tracker, message.output_channel)
            elif (
                isinstance(event, SessionEnded)
                and event.metadata.get("_reason") == BOT_DISCONNECTED_REASON
            ):
                await message.output_channel.hangup(tracker.sender_id)

    @staticmethod
    async def _send_bot_messages(
        events: List[Event],
        tracker: DialogueStateTracker,
        output_channel: OutputChannel,
    ) -> OutputDeliveryResult:
        """Send all the bot messages that are logged in the events array."""
        result = OutputDeliveryResult()
        for event in events:
            if not isinstance(event, BotUttered):
                continue

            if event.metadata.get(STREAMED_RESPONSE_FULLY_DELIVERED_KEY):
                structlogger.debug(
                    "rasa.core.processor._send_bot_messages.skip_streamed_chunk",
                    text=event.text,
                )
                continue

            message = event.message()
            if event.metadata.get(STREAMED_RESPONSE_TEXT_DELIVERED_KEY):
                # The text was already delivered as chunks; retain non-text payloads.
                message["text"] = ""

            delivery = await output_channel.send_response(tracker.sender_id, message)
            result.extend(delivery)
        return result

    @observe(
        name="rasa.message_processing",
        as_type="generation",
        capture_input=False,
        capture_output=False,
    )
    async def handle_message(
        self, message: UserMessage
    ) -> Optional[List[Dict[str, Any]]]:
        """Handle a single message with this processor."""
        from rasa.tracing.engine_token_usage import bind_engine_token_session

        with (
            conversation_log_context(message.sender_id),
            bind_engine_token_session(message.sender_id),
        ):
            trace_context = self._setup_langfuse_trace_for_turn(message)

            # preprocess message if necessary
            await message.output_channel.notify_message_processing_started()
            self.time_turn_start = time.time()

            tracker = await self.log_message(message, should_save_tracker=False)
            turn_event_start_idx = len(tracker.events)

            if self.model_metadata.training_type == TrainingType.NLU:
                rasa.shared.utils.io.raise_warning(
                    "No core model. Skipping action prediction and execution.",
                    docs=DOCS_URL_NLU_BASED_POLICIES,
                )
                self._update_langfuse_turn_output(
                    message=message,
                    tracker=tracker,
                    turn_event_start_idx=turn_event_start_idx,
                    trace_context=trace_context,
                )
                await self.save_tracker(tracker)
                await complete_channel_turn(message.output_channel, tracker)
                return None

            tracker = await self._run_engine_turn(message, tracker)

            return await self._finalize_turn(
                message=message,
                tracker=tracker,
                turn_event_start_idx=turn_event_start_idx,
                trace_context=trace_context,
            )

    async def _finalize_turn(
        self,
        message: UserMessage,
        tracker: DialogueStateTracker,
        turn_event_start_idx: int,
        trace_context: Optional[Dict[str, str]],
    ) -> Optional[List[Dict[str, Any]]]:
        """Persist the turn, notify the channel and return any collected messages.

        Shared tail for every engine version: update the Langfuse trace output,
        save the tracker, notify the channel that processing completed, trigger
        anonymization and, for a ``CollectingOutputChannel``, return its messages.

        The tracker is attached here so a channel that maps the finished turn
        (A2A) sees the stack after the engine returns. CALM also attaches
        inside ``execute_side_effects``; Mantle does not run that path.
        """
        self._update_langfuse_turn_output(
            message=message,
            tracker=tracker,
            turn_event_start_idx=turn_event_start_idx,
            trace_context=trace_context,
        )
        await self.save_tracker(tracker)
        await complete_channel_turn(message.output_channel, tracker)
        self.trigger_anonymization(tracker)

        if isinstance(message.output_channel, CollectingOutputChannel):
            return message.output_channel.messages

        return None

    # TODO(ENG-2874): define sub-agent / A2A handling (incl. this async-update
    # delivery path) for the Mantle engine.
    @staticmethod
    def _has_deliverable_async_agent_update(tracker: DialogueStateTracker) -> bool:
        top_frame = tracker.stack.top()
        return isinstance(top_frame, AgentStackFrame) and top_frame.state in {
            AgentState.PROCESSING,
            AgentState.WAITING_FOR_INPUT_FROM_PUSH_NOTIFICATION,
            AgentState.COMPLETED,
            AgentState.TERMINAL,
        }

    async def deliver_pending_async_update(
        self,
        conversation_id: str,
        output_channel: OutputChannel,
        input_channel: Optional[str] = None,
    ) -> bool:
        """Deliver a pending async agent update without logging a new user message.

        The async task result processor persists task updates on agent stack frames.
        Channels that own a live connection can call this method after receiving an
        async-task update notification. The method re-checks tracker state under the
        conversation lock so duplicate notifications and races are harmless.
        """
        from rasa.agents.core.cancellation import CancellationToken

        async with self.lock_store.lock(conversation_id):
            tracker = await self.get_tracker(conversation_id)
            if input_channel and tracker.get_latest_input_channel() != input_channel:
                return False
            if not self._has_deliverable_async_agent_update(tracker):
                return False

            token = CancellationToken()
            self.register_cancellation_token(conversation_id, token)
            try:
                await output_channel.notify_message_processing_started()
                await self.process_tracker(output_channel, tracker, token)
                await self.save_tracker(tracker)
            finally:
                self.unregister_cancellation_token(conversation_id)

        await complete_channel_turn(output_channel, tracker)
        return True

    async def handle_voice_conversation(
        self,
        input_queue: "ConversationQueue[InputEvent]",
        output_channel: OutputChannel,
        sender_id: str,
        channel_controller: "Optional[ChannelController]" = None,
    ) -> None:
        """Drive a voice conversation for its full duration.

        Manages the full call lifecycle using two async tasks. The event composer
        transforms raw events from `input_queue` while the interaction loop processes
        composed events.

        The lock is acquired per turn, not for the duration of the call, so it never
        risks expiring on long calls.

        Args:
            input_queue: Raw event queue pushed by the voice channel.
            output_channel: Output channel for bot responses.
            sender_id: The conversation / sender ID.
            channel_controller: Handle the voice channel gives to event-composition
                handlers for input-channel lifecycle actions such as hangup.
        """
        structlogger.info(
            "processor.handle_voice_conversation.start",
            sender_id=sender_id,
        )
        event_composer = EventComposer(
            raw_event_queue=input_queue,
            sender_id=sender_id,
            resolve_active_dtmf_collect=self._resolve_active_dtmf_collect,
            channel_controller=channel_controller,
            on_barge_in_accepted=lambda: self._handle_voice_barge_in(
                output_channel, sender_id
            ),
            on_session_ended=lambda: self.cancel_background_tasks(sender_id),
        )
        interaction_event_queue = event_composer.interaction_event_queue
        transform_raw_events_task = asyncio.create_task(event_composer.run())
        conversation_loop_task = asyncio.create_task(
            self._run_voice_conversation_loop(
                interaction_event_queue,
                output_channel,
                sender_id,
                event_composer,
            )
        )
        tasks = {transform_raw_events_task, conversation_loop_task}
        try:
            done, pending = await asyncio.wait(
                tasks,
                return_when=asyncio.FIRST_EXCEPTION,
            )
            for task in done:
                exception = task.exception()
                if exception is not None:
                    for pending_task in pending:
                        pending_task.cancel()
                    await asyncio.gather(*pending, return_exceptions=True)
                    raise exception

            await asyncio.gather(*pending)
        finally:
            for task in tasks:
                if not task.done():
                    task.cancel()
            await asyncio.gather(*tasks, return_exceptions=True)

    def _setup_langfuse_trace_for_turn(
        self,
        message: UserMessage,
    ) -> Optional[Dict[str, str]]:
        """Initialise the Langfuse trace and span for the current turn.

        Merges any existing trace context into the message metadata so
        downstream spans are linked to the same trace, then records turn-level
        metadata (sender, model, assistant) on both the trace and the root span.

        Returns the trace context dict if one was found, otherwise None.
        """
        metadata = message.metadata or {}
        trace_context = get_current_trace_context(sender_id=message.sender_id)
        if trace_context:
            merged_metadata = dict(metadata)
            merged_metadata.update(trace_context)
            message.metadata = merged_metadata
            metadata = merged_metadata
        trace_input = message.text or ""
        update_current_trace_for_turn(
            sender_id=message.sender_id,
            message_id=message.message_id,
            user_id=metadata.get(USER_ID),
            assistant_id=self.model_metadata.assistant_id,
            model_id=self.model_metadata.model_id,
            input_channel=message.input_channel,
            tags=["rasa-core", "message-processing"],
            trace_input=trace_input,
        )
        update_current_span_metadata(
            metadata={
                "prompt_type": "message_processing",
                "sender_id": message.sender_id,
                "message_id": message.message_id,
                "component": self.__class__.__name__,
            },
            span_input=trace_input,
        )
        return trace_context

    def _update_langfuse_turn_output(
        self,
        message: UserMessage,
        tracker: DialogueStateTracker,
        turn_event_start_idx: int,
        trace_context: Optional[Dict[str, str]] = None,
    ) -> None:
        """Attach per-turn bot responses to the current Langfuse trace/span."""
        turn_events = list(tracker.events)[turn_event_start_idx:]
        if trace_context:
            for event in turn_events:
                event.metadata.update(trace_context)
        turn_bot_messages: List[Dict[str, Any]] = [
            event.message() for event in turn_events if isinstance(event, BotUttered)
        ]
        bot_texts = [m.get("text") for m in turn_bot_messages if m.get("text")]
        trace_output = "\n".join(bot_texts) if bot_texts else ""
        trace_input = message.text or ""
        metadata = message.metadata or {}
        update_current_trace_for_turn(
            sender_id=message.sender_id,
            message_id=message.message_id,
            user_id=metadata.get(USER_ID),
            assistant_id=self.model_metadata.assistant_id,
            model_id=self.model_metadata.model_id,
            input_channel=message.input_channel,
            trace_input=trace_input,
            trace_output=trace_output,
        )
        update_current_span_metadata(
            span_input=trace_input,
            span_output=trace_output,
            metadata={"bot_responses": turn_bot_messages},
        )

    def trigger_anonymization(self, tracker: DialogueStateTracker) -> None:
        if self.privacy_manager is None:
            structlogger.debug(
                "processor.trigger_anonymization.skipping.pii_management_not_enabled",
            )
            return None

        if not self.privacy_manager.event_brokers:
            structlogger.debug(
                "processor.trigger_anonymization.skipping.no_event_brokers",
            )
            return None

        structlogger.info(
            "rasa.core.processor.trigger_anonymization",
            sender_id=tracker.sender_id,
            event_info="Triggering anonymization for publishing anonymized "
            "events to the event broker.",
        )
        return self.privacy_manager.run(tracker)

    async def _update_tracker_session(
        self,
        tracker: DialogueStateTracker,
        output_channel: OutputChannel,
        metadata: Optional[Dict] = None,
    ) -> None:
        """Check the current session in `tracker` and update it if needed.

        An 'action_session_start' is run if the tracker has no events (brand new
        conversation), or if the latest session has expired and
        `session_config.start_session_after_expiry` is True.

        Args:
            metadata: Data sent from client associated with the incoming user message.
            tracker: Tracker to inspect.
            output_channel: Output channel for potential utterances in a custom
                `ActionSessionStart`.
        """
        # Don't start a new session if the tracker is terminated
        # Terminated conversations cannot be resumed
        if tracker.terminated:
            structlogger.warning(
                "rasa.core.processor._update_tracker_session",
                event_info=(
                    "Not starting a new session as the conversation "
                    "is already terminated."
                ),
                sender_id=tracker.sender_id,
            )
            return

        # Start a new session if tracker has no events (brand new conversation)
        # or if session expired and config says to auto-start a new session
        should_start_new_session = not tracker.applied_events() or (
            self.session_config.start_session_after_expiry
            and self._has_session_expired(tracker)
        )
        if should_start_new_session:
            structlogger.debug(
                "rasa.core.processor._update_tracker_session",
                event_info="Starting a new session.",
                sender_id=tracker.sender_id,
            )

            # Purge stale user flow frames before sending the tracker to a
            # custom action server. Residual frames from a previous session
            # (e.g. a flow whose steps were renamed across an upgrade) would
            # otherwise travel inside the payload and surface as
            # InvalidFlowStepIdException in any downstream handler that walks
            # the stack — including the action-failure handler at
            # `_get_events_from_action_execution_failure`.
            await self._purge_stale_frames_for_turn(tracker)

            # Persist channel session metadata before engine-specific
            # initialisation. CALM v1 writes ``SlotSet``; Mantle no-ops here and
            # records the value after ``SessionStarted`` so it survives the reset.
            self._record_session_start_metadata(tracker, metadata)

            await self._start_new_session(tracker, output_channel, metadata)

    def _record_session_start_metadata(
        self,
        tracker: DialogueStateTracker,
        metadata: Optional[Dict] = None,
    ) -> None:
        """Persist channel metadata for a new session as a ``SlotSet``.

        Engine seam invoked by ``_update_tracker_session`` before
        ``_start_new_session``. CALM v1 keeps the legacy slot write so
        ``action_session_start`` can carry it over; Mantle overrides this as a
        no-op and writes a ``MemorySet`` after ``SessionStarted`` instead.
        """
        if metadata:
            tracker.update(SlotSet(SESSION_START_METADATA_SLOT, metadata), self.domain)

    async def fetch_tracker_and_update_session(
        self,
        sender_id: str,
        output_channel: Optional[OutputChannel] = None,
        metadata: Optional[Dict] = None,
    ) -> DialogueStateTracker:
        """Fetches tracker for `sender_id` and updates its conversation session.

        If a new tracker is created, `action_session_start` is run.

        Args:
            metadata: Data sent from client associated with the incoming user message.
            output_channel: Output channel associated with the incoming user message.
            sender_id: Conversation ID for which to fetch the tracker.

        Returns:
              Tracker for `sender_id`.
        """
        user_id = metadata.get(USER_ID) if metadata else None
        tracker = await self.get_tracker(sender_id, user_id)

        await self._update_tracker_session(tracker, output_channel, metadata)

        return tracker

    async def fetch_tracker_with_initial_session(
        self,
        sender_id: str,
        output_channel: Optional[OutputChannel] = None,
        metadata: Optional[Dict] = None,
    ) -> DialogueStateTracker:
        """Fetches tracker for `sender_id` and runs a session start on a new one.

        Args:
            metadata: Data sent from client associated with the incoming user message.
            output_channel: Output channel associated with the incoming user message.
            sender_id: Conversation ID for which to fetch the tracker.

        Returns:
              Tracker for `sender_id`.
        """
        user_id = metadata.get(USER_ID) if metadata else None
        tracker = await self.get_tracker(sender_id, user_id)

        # run session start only if the tracker is empty
        if not tracker.events:
            await self._update_tracker_session(tracker, output_channel, metadata)

        return tracker

    async def get_tracker(
        self, conversation_id: str, user_id: Optional[str] = None
    ) -> DialogueStateTracker:
        """Get the tracker for a conversation.

        In contrast to `fetch_tracker_and_update_session` this does not add any
        `action_session_start` or `session_start` events at the beginning of a
        conversation.

        Args:
            conversation_id: The ID of the conversation for which the history should be
                retrieved.
            user_id: The ID of the user for which the history should be retrieved.

        Returns:
            Tracker for the conversation. Creates an empty tracker in case it's a new
            conversation.
        """
        conversation_id = conversation_id or DEFAULT_SENDER_ID

        tracker = await self.tracker_store.get_or_create_tracker(
            conversation_id, append_action_listen=False, user_id=user_id
        )
        tracker.model_id = self.model_metadata.model_id
        tracker.model_name = self.model_filename
        if tracker.assistant_id is None:
            tracker.assistant_id = self.model_metadata.assistant_id
        if tracker.user_id is None and user_id is not None:
            tracker.user_id = user_id
        return tracker

    async def fetch_full_tracker_with_initial_session(
        self,
        conversation_id: str,
        output_channel: Optional[OutputChannel] = None,
        metadata: Optional[Dict] = None,
    ) -> DialogueStateTracker:
        """Get the full tracker for a conversation, including events after a restart.

        Args:
            conversation_id: The ID of the conversation for which the history should be
                retrieved.
            output_channel: Output channel associated with the incoming user message.
            metadata: Data sent from client associated with the incoming user message.

        Returns:
            Tracker for the conversation. Creates an empty tracker with a new session
            initialized in case it's a new conversation.
        """
        user_id = metadata.get(USER_ID) if metadata else None
        conversation_id = conversation_id or DEFAULT_SENDER_ID

        tracker = await self.tracker_store.get_or_create_full_tracker(
            conversation_id, False
        )
        tracker.model_id = self.model_metadata.model_id
        tracker.model_name = self.model_filename

        if tracker.assistant_id is None:
            tracker.assistant_id = self.model_metadata.assistant_id

        if not tracker.events:
            await self._update_tracker_session(tracker, output_channel, metadata)

        if tracker.user_id is None and user_id is not None:
            tracker.user_id = user_id

        return tracker

    async def get_trackers_for_all_conversation_sessions(
        self, conversation_id: str
    ) -> List[DialogueStateTracker]:
        """Fetches all trackers for a conversation.

        Individual trackers are returned for each conversation session found
        for `conversation_id`.

        Args:
            conversation_id: The ID of the conversation for which the trackers should
                be retrieved.

        Returns:
            Trackers for the conversation.
        """
        conversation_id = conversation_id or DEFAULT_SENDER_ID

        tracker = await self.tracker_store.retrieve_full_tracker(conversation_id)

        return rasa.shared.core.trackers.get_trackers_for_conversation_sessions(tracker)

    async def log_message(
        self,
        message: UserMessage,
        should_save_tracker: bool = True,
    ) -> DialogueStateTracker:
        """Log `message` on tracker belonging to the message's conversation_id.

        Optionally save the tracker if `should_save_tracker` is `True`. Tracker saving
        can be skipped if the tracker returned by this method is used for further
        processing and saved at a later stage.
        """
        tracker = await self.fetch_tracker_and_update_session(
            message.sender_id, message.output_channel, message.metadata
        )

        # Purge stale frames before the command generator runs so it sees a
        # clean stack. Without this, commands are baked into parse_data using the
        # stale context, causing InvalidFlowIdException when the policy later
        # tries to advance a flow that no longer exists in the model.
        await self._purge_stale_frames_for_turn(tracker)

        await self._handle_message_with_tracker(message, tracker)

        if should_save_tracker:
            await self.save_tracker(tracker)

        return tracker

    async def handle_session_timeout(
        self,
        sender_id: str,
        session_id: Optional[str],
        scheduled_time: Optional[float] = None,
    ) -> None:
        """Handle a session timeout triggered by the timer.

        This method is called when the session timer fires due to inactivity.
        It acquires a lock, re-fetches the tracker, validates the session,
        and emits the ConversationInactive event if appropriate.

        Args:
            sender_id: The conversation ID.
            session_id: The session ID when the timer was scheduled.
            scheduled_time: When the timer was scheduled (Unix timestamp).
                If provided, expiration is skipped when a user message arrived
                after this time (avoids race in multi-pod deployments).
        """
        self.cancel_background_tasks(sender_id)

        async with self.lock_store.lock(sender_id):
            tracker = await self.get_tracker(sender_id)

            # Validate: conversation must not be terminated
            if tracker.terminated:
                structlogger.debug(
                    "processor.session_timeout.already_terminated",
                    sender_id=sender_id,
                )
                return

            # Validate: session ID must match (session hasn't restarted)
            if session_id and tracker.current_session_id != session_id:
                structlogger.debug(
                    "processor.session_timeout.session_mismatch",
                    sender_id=sender_id,
                    expected_session_id=session_id,
                    actual_session_id=tracker.current_session_id,
                )
                return

            # Validate: conversation must not already be inactive
            if tracker.inactive:
                structlogger.debug(
                    "processor.session_timeout.already_inactive",
                    sender_id=sender_id,
                )
                return

            # Message timestamp check: cancel expiration if a user message
            # arrived after the timer was scheduled (multi-pod race safeguard).
            if scheduled_time is not None:
                user_uttered = tracker.get_last_event_for(UserUttered)
                if (
                    user_uttered is not None
                    and isinstance(user_uttered, UserUttered)
                    and user_uttered.timestamp > scheduled_time
                ):
                    structlogger.debug(
                        "processor.session_timeout.message_after_timer",
                        sender_id=sender_id,
                        session_id=session_id,
                    )
                    return

            # Emit ConversationInactive event
            self._cleanup_on_session_timeout(tracker)
            event = ConversationInactive()
            structlogger.info(
                "processor.session_timeout.conversation_inactive",
                sender_id=sender_id,
                session_id=session_id,
            )

            tracker.update(event, self.domain)
            await self.save_tracker(tracker)

    async def parse_message(
        self,
        message: UserMessage,
        tracker: Optional[DialogueStateTracker] = None,
        only_output_properties: bool = True,
    ) -> Dict[str, Any]:
        """Interprets the passed message.

        Args:
            message: Message to handle.
            tracker: Tracker to use.
            only_output_properties: If `True`, restrict the output to
                Message.only_output_properties.

        Returns:
            Parsed data extracted from the message.
        """
        parse_data = await self._parse_message_for_engine(
            message=message,
            tracker=tracker,
            only_output_properties=only_output_properties,
        )

        structlogger.debug(
            "processor.message.parse",
            parse_data_text=parse_data.get(TEXT),
            parse_data_intent=parse_data.get(INTENT),
            parse_data_entity_count=len(parse_data.get(ENTITIES) or []),
        )

        self._initialise_consecutive_silence_timeout_slots(parse_data, tracker)

        return parse_data

    async def _handle_session_timer_events(
        self,
        events: List[Event],
        tracker: DialogueStateTracker,
    ) -> None:
        """Handle session timer scheduling based on events.

        Schedules a timer when SessionStarted is detected.
        Cancels timer when SessionEnded is detected.

        Args:
            events: List of events to process.
            tracker: The current conversation tracker.
        """
        if not self.timer_manager:
            return

        for event in events:
            if isinstance(event, SessionStarted):
                await self._schedule_session_timer(tracker)
            elif isinstance(event, (ConversationInactive, SessionEnded)):
                await self.timer_manager.cancel_timer(tracker.sender_id)

    async def _schedule_session_timer(
        self,
        tracker: DialogueStateTracker,
    ) -> None:
        """Schedule a session inactivity timer.

        Args:
            tracker: The current conversation tracker.
        """
        if not self.timer_manager:
            return

        # Don't schedule timer if sessions are disabled (expiration_time=0)
        if self.session_config.session_expiration_time <= 0:
            return

        timeout_seconds = self.session_config.session_expiration_time * 60

        await self.timer_manager.schedule_timer(
            sender_id=tracker.sender_id,
            session_id=tracker.current_session_id,
            timeout_seconds=timeout_seconds,
            callback=self.handle_session_timeout,
        )

        structlogger.debug(
            "processor.session_timer.scheduled",
            sender_id=tracker.sender_id,
            session_id=tracker.current_session_id,
            timeout_minutes=self.session_config.session_expiration_time,
        )

    async def _reschedule_session_timer(
        self,
        tracker: DialogueStateTracker,
    ) -> None:
        """Schedule the session inactivity timer after user activity.

        Args:
            tracker: The current conversation tracker.
        """
        if not self.timer_manager:
            return

        if self.session_config.session_expiration_time <= 0:
            return

        # Don't reschedule timer for terminated conversations
        if tracker.terminated:
            return

        timeout_seconds = self.session_config.session_expiration_time * 60
        sender_id = tracker.sender_id
        session_id = tracker.current_session_id

        await self.timer_manager.schedule_timer(
            sender_id=sender_id,
            session_id=session_id,
            timeout_seconds=timeout_seconds,
            callback=self.handle_session_timeout,
        )

        structlogger.debug(
            "processor.session_timer.rescheduled",
            sender_id=sender_id,
            session_id=session_id,
            timeout_minutes=self.session_config.session_expiration_time,
        )

    def _has_session_expired(self, tracker: DialogueStateTracker) -> bool:
        """Determine whether the latest session in `tracker` has expired.

        Args:
            tracker: Tracker to inspect.

        Returns:
            `True` if the session in `tracker` has expired, `False` otherwise.
        """
        if not self.session_config.are_sessions_enabled():
            return False

        has_expired = tracker.is_session_time_expired(
            self.session_config.session_expiration_time
        )
        if has_expired:
            structlogger.debug(
                "rasa.core.processor.has_session_expired",
                event_info="The latest session has expired.",
                sender_id=tracker.sender_id,
            )

        return has_expired

    async def save_tracker(self, tracker: DialogueStateTracker) -> None:
        """Save the given tracker to the tracker store.

        Args:
            tracker: Tracker to be saved.
        """
        await self.tracker_store.save(tracker)

    async def record_event_on_tracker(
        self, tracker: DialogueStateTracker, event: Event
    ) -> None:
        """Record a tracker event and persist the updated tracker.

        Args:
            tracker: Tracker to update and save.
            event: Event to record on the tracker.
        """
        tracker.update(event, self.domain)
        await self.save_tracker(tracker)

    @staticmethod
    def _initialise_consecutive_silence_timeout_slots(
        parse_data: Dict[str, Any],
        tracker: DialogueStateTracker,
    ) -> None:
        # resetting timeouts variables whenever something that is not a timeout occurs
        if (
            parse_data.get(INTENT, {}).get(INTENT_NAME_KEY)
            != USER_INTENT_SILENCE_TIMEOUT
            and tracker
        ):
            if (
                SLOT_CONSECUTIVE_SILENCE_TIMEOUTS in tracker.slots
                and tracker.slots[SLOT_CONSECUTIVE_SILENCE_TIMEOUTS].value != 0.0
            ):
                tracker.update(SlotSet(SLOT_CONSECUTIVE_SILENCE_TIMEOUTS, 0.0))

    async def _handle_message_with_tracker(
        self, message: UserMessage, tracker: DialogueStateTracker
    ) -> None:
        # Gracefully handle messages sent to terminated conversations
        if tracker.terminated:
            structlogger.debug(
                "rasa.core.processor.handle_message_with_tracker.terminated_conversation",
                event_info=(
                    f"Ignoring message from user as conversation {tracker.sender_id} "
                    "was terminated with a SessionEnded event."
                ),
                sender_id=tracker.sender_id,
                user_message=message.text,
            )
            return

        if message.parse_data:
            parse_data = message.parse_data
        else:
            parse_data = await self.parse_message(message, tracker)

        message_metadata = dict(message.metadata) if message.metadata else None
        # A2A client slot-command prefill only applies to the A2A input channel;
        # other channels must not inject orchestrator slot commands from metadata.
        if (
            message.input_channel == RASA_A2A_INPUT_CHANNEL
            and message_metadata is not None
        ):
            prefill_commands = self._engine_prefill_commands(
                message_metadata, parse_data
            )
            if prefill_commands:
                parse_data.setdefault(COMMANDS, []).extend(prefill_commands)

        # don't ever directly mutate the tracker
        # - instead pass its events to log
        tracker.update(
            UserUttered(
                message.text,
                parse_data[INTENT],
                parse_data[ENTITIES],
                parse_data,
                input_channel=message.input_channel,
                message_id=message.message_id,
                metadata=message_metadata,
            ),
            self.domain,
        )

        # Reschedule session timer on user activity
        await self._reschedule_session_timer(tracker)

        if parse_data[ENTITIES]:
            self._log_turn_slots(tracker)

        plugin_manager().hook.after_new_user_message(tracker=tracker)

        structlogger.debug(
            "rasa.core.processor.handle_message_with_tracker",
            event_info="Logged UserUtterance.",
            user_message=message.text,
            number_of_events=len(tracker.events),
        )


class CalmMessageProcessor(BaseMessageProcessor):
    """Message processor for the CALM v1 / NLU dialogue engine.

    Implements every engine-divergent method declared abstract on
    :class:`MessageProcessor` / :class:`BaseMessageProcessor`, plus the v1-only
    private helpers they rely on (NLU parsing, the policy prediction loop,
    action execution, reminders and command processing).
    """

    def __init__(
        self,
        model_path: Union[str, Path],
        tracker_store: rasa.core.tracker_stores.tracker_store.TrackerStore,
        lock_store: LockStore,
        generator: NaturalLanguageGenerator,
        action_endpoint: Optional[EndpointConfig] = None,
        max_number_of_predictions: int = MAX_NUMBER_OF_PREDICTIONS,
        max_number_of_predictions_calm: int = MAX_NUMBER_OF_PREDICTIONS_CALM,
        on_circuit_break: Optional[LambdaType] = None,
        http_interpreter: Optional[RasaNLUHttpInterpreter] = None,
        endpoints: Optional["AvailableEndpoints"] = None,
        privacy_manager: Optional["BackgroundPrivacyManager"] = None,
        timer_manager: Optional["SessionTimerManager"] = None,
        model_archive: Optional[Union[str, Path]] = None,
    ) -> None:
        """Initialise a CALM v1 / NLU message processor.

        Runs the shared :class:`BaseMessageProcessor` construction, then wires the
        v1-only state: the NLG generator, the action endpoint, the optional HTTP
        NLU interpreter, the prediction limits, and the graph runner (handed off
        from Base's ``_load_model`` via ``self._loaded_graph_runner`` to avoid a
        second model load). ``is_calm_assistant`` is computed last because it
        inspects the graph runner.
        """
        super().__init__(
            model_path=model_path,
            tracker_store=tracker_store,
            lock_store=lock_store,
            generator=generator,
            action_endpoint=action_endpoint,
            max_number_of_predictions=max_number_of_predictions,
            max_number_of_predictions_calm=max_number_of_predictions_calm,
            on_circuit_break=on_circuit_break,
            http_interpreter=http_interpreter,
            endpoints=endpoints,
            privacy_manager=privacy_manager,
            timer_manager=timer_manager,
            model_archive=model_archive,
        )
        self.nlg = generator
        self.action_endpoint = action_endpoint
        self.http_interpreter = http_interpreter
        self.max_number_of_predictions = max_number_of_predictions
        self.max_number_of_predictions_calm = max_number_of_predictions_calm
        # The graph runner was loaded by Base and parked on a neutral attribute;
        # adopt it here without re-loading. Must be set before computing
        # ``is_calm_assistant`` because that inspects the graph schema.
        self.graph_runner: GraphRunner = self._loaded_graph_runner
        self.is_calm_assistant = self._is_calm_assistant()

    def _get_action(
        self, action_name: str
    ) -> Optional[rasa.core.actions.action.Action]:
        return rasa.core.actions.action.action_for_name_or_text(
            action_name, self.domain, self.action_endpoint
        )

    @staticmethod
    def message_contains_commands(latest_message: Optional[UserUttered]) -> bool:
        """Check if the latest message contains commands."""
        if latest_message is None:
            return False

        commands = [
            Command.command_from_json(command) for command in latest_message.commands
        ]
        filtered_commands = [
            command
            for command in commands
            if not (
                isinstance(command, SetSlotCommand)
                and command.name == ROUTE_TO_CALM_SLOT
            )
            and not isinstance(command, NoopCommand)
        ]

        return len(filtered_commands) > 0

    def _is_calm_assistant(self) -> bool:
        """Inspects the nodes of the graph schema to decide if we are in CALM.

        To determine whether we are in CALM mode, we check if any node is
        associated with the `FlowPolicy`, which is indicative of a
        CALM assistant setup.

        Returns:
            bool: True if any node in the graph schema uses `FlowPolicy`.
        """
        flow_policy_class_path = "rasa.core.policies.flow_policy.FlowPolicy"
        return self._is_component_present_in_graph_nodes(flow_policy_class_path)

    @staticmethod
    def _is_coexistence_assistant(tracker: DialogueStateTracker) -> bool:
        """Inspect the tracker to decide if we are in coexistence.

        Returns:
            bool: True if the tracker contains the routine slot.
        """
        return tracker.slots.get(ROUTE_TO_CALM_SLOT) is not None

    def _is_component_present_in_graph_nodes(self, component_path: str) -> bool:
        """Check if a component is present in the graph nodes.

        Args:
            component_path: The path of the component to check for.

        Returns:
            `True` if the component is present in the graph nodes, `False` otherwise.
        """
        # Get the graph schema's nodes from the graph runner.
        nodes: dict[str, Any] = self.graph_runner._graph_schema.nodes  # type: ignore[attr-defined]

        for node_name, schema_node in nodes.items():
            if (
                schema_node.uses is not None
                and f"{schema_node.uses.__module__}.{schema_node.uses.__name__}"
                == component_path
            ):
                return True

        return False

    @staticmethod
    def _expire_processing_agent_frames(tracker: DialogueStateTracker) -> None:
        now = time.time()
        stack = tracker.stack
        changed = False
        for frame in stack.frames:
            if not isinstance(frame, AgentStackFrame):
                continue
            if frame.state != AgentState.PROCESSING:
                continue
            if frame.processing_deadline is None or frame.processing_deadline > now:
                continue
            frame.state = AgentState.TERMINAL
            frame.processing_deadline = None
            changed = True
        if changed:
            tracker.update_stack(stack)

    @staticmethod
    def _log_slots(tracker: DialogueStateTracker) -> None:
        # Log currently set slots
        slots = {
            s.name: s.value
            for s in tracker.slots.values()
            if s.value is not None and s.name not in SLOTS_EXCLUDED_FOR_AGENT
        }

        structlogger.debug("processor.slots.user_slots", slots=slots)

    def _check_for_unseen_features(self, parse_data: Dict[str, Any]) -> None:
        """Warns the user if the NLU parse data contains unrecognized features.

        Checks intents and entities picked up by the NLU parsing
        against the domain and warns the user of those that don't match.
        Also considers a list of default intents that are valid but don't
        need to be listed in the domain.

        Args:
            parse_data: Message parse data to check against the domain.
        """
        if not self.domain or self.domain.is_empty():
            return

        intent = parse_data[INTENT][INTENT_NAME_KEY]
        if intent and intent not in self.domain.intents:
            rasa.shared.utils.io.raise_warning(
                f"Parsed an intent '{intent}' "
                f"which is not defined in the domain. "
                f"Please make sure all intents are listed in the domain.",
                docs=DOCS_URL_DOMAINS,
            )

        entities = parse_data[ENTITIES] or []
        for element in entities:
            entity = element["entity"]
            if entity and entity not in self.domain.entities:
                rasa.shared.utils.io.raise_warning(
                    f"Parsed an entity '{entity}' "
                    f"which is not defined in the domain. "
                    f"Please make sure all entities are listed in the domain.",
                    docs=DOCS_URL_DOMAINS,
                )

    def _update_full_retrieval_intent(self, parse_data: Dict[str, Any]) -> None:
        """Update the parse data with the full retrieval intent.

        Args:
            parse_data: Message parse data to update.
        """
        intent_name = parse_data.get(INTENT, {}).get(INTENT_NAME_KEY)
        response_selector = parse_data.get(RESPONSE_SELECTOR, {})
        all_retrieval_intents = response_selector.get("all_retrieval_intents", [])
        if intent_name and intent_name in all_retrieval_intents:
            retrieval_intent = (
                response_selector.get(intent_name, {})
                .get(RESPONSE, {})
                .get(INTENT_RESPONSE_KEY)
            )
            parse_data[INTENT][FULL_RETRIEVAL_INTENT_NAME_KEY] = retrieval_intent

    # ------------------------------------------------------------------
    # Engine seams (implementations of the BaseMessageProcessor abstract
    # seams for the CALM v1 / NLU engine).
    # ------------------------------------------------------------------

    async def _start_new_session(
        self,
        tracker: DialogueStateTracker,
        output_channel: OutputChannel,
        metadata: Optional[Dict] = None,
    ) -> None:
        """Run ``action_session_start`` through the v1 action machinery."""
        action_session_start = self._get_action(ACTION_SESSION_START_NAME)
        await self._run_action(
            action=action_session_start,
            tracker=tracker,
            output_channel=output_channel,
            nlg=self.nlg,
            prediction=PolicyPrediction.for_action_name(
                self.domain, ACTION_SESSION_START_NAME
            ),
        )

    @property
    def session_config(self) -> SessionConfig:
        """CALM v1 sources the session config from the model's domain."""
        return self.domain.session_config

    async def _resolve_turn_flows(self) -> Optional[FlowsList]:
        """Return the model's flows for CALM assistants, else ``None``."""
        if self.is_calm_assistant:
            return await self.get_flows()
        return None

    async def _resolve_active_dtmf_collect(
        self, sender_id: str
    ) -> Optional[ActiveDTMFCollect]:
        """Map the active CALM DTMF step to the shared voice contract."""
        tracker = await self.get_tracker(sender_id)
        flows = await self.get_flows()
        collect_step = self._get_active_dtmf_collect_step(tracker, flows)
        if collect_step is None or collect_step.dtmf is None:
            return None

        return ActiveDTMFCollect(
            field_name=collect_step.collect,
            length=collect_step.dtmf.length,
            finish_on_key=collect_step.dtmf.finish_on_key,
            allow_audio_input=collect_step.dtmf.allow_audio_input,
        )

    @staticmethod
    def _get_active_dtmf_collect_step(
        tracker: DialogueStateTracker, flows: FlowsList
    ) -> Optional[CollectInformationFlowStep]:
        """Return the active CALM DTMF collect step, if one exists."""
        top_frame = tracker.stack.top()
        if not isinstance(top_frame, CollectInformationPatternFlowStackFrame):
            return None

        for frame in reversed(tracker.stack.frames):
            if not isinstance(frame, UserFlowStackFrame):
                continue

            step = frame.step(flows)
            if (
                isinstance(step, CollectInformationFlowStep)
                and step.collect == top_frame.collect
                and step.dtmf is not None
            ):
                return step

        return None

    async def _purge_stale_frames_for_turn(self, tracker: DialogueStateTracker) -> None:
        """Purge stale user-flow frames for CALM assistants."""
        flows = await self._resolve_turn_flows()
        if flows is None:
            return
        self._purge_stale_user_flow_frames(tracker, flows)

    def _cleanup_on_session_timeout(self, tracker: DialogueStateTracker) -> None:
        """Expire stale processing-agent frames on session timeout."""
        self._expire_processing_agent_frames(tracker)

    def _engine_prefill_commands(
        self, message_metadata: Dict[str, Any], parse_data: Dict[str, Any]
    ) -> List[Dict[str, Any]]:
        """Return A2A-client set-slot prefill commands for the incoming message."""
        return self._set_a2a_metadata_set_slot_commands(message_metadata, parse_data)

    def _log_turn_slots(self, tracker: DialogueStateTracker) -> None:
        """Log the domain slots set on the tracker for the current turn."""
        self._log_slots(tracker)

    @staticmethod
    def _a2a_client_slot_commands_to_merge(
        parse_commands: list[dict[str, Any]],
        a2a_client_slot_commands: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        """Return A2A pre-fill commands for slots not extracted from the user message.

        Orchestrator slot snapshots may lag behind the latest user turn. When command
        generation already produced a ``SetSlotCommand`` for a slot, that value wins.
        """
        user_extracted_slot_names = {
            command["name"]
            for command in parse_commands
            if command.get("command") == SET_SLOT_COMMAND and "name" in command
        }
        return [
            command
            for command in a2a_client_slot_commands
            if command.get("name") not in user_extracted_slot_names
        ]

    @staticmethod
    def _set_a2a_metadata_set_slot_commands(
        message_metadata: Dict[str, Any], parse_data: Dict[str, Any]
    ) -> List[Dict[str, Any]]:
        a2a_client_slot_commands: List[Dict[str, Any]] = []
        raw_a2a_commands = message_metadata.pop(
            A2A_CLIENT_SLOT_COMMANDS_METADATA_KEY, None
        )
        if isinstance(raw_a2a_commands, list):
            a2a_client_slot_commands = [
                command
                for command in raw_a2a_commands
                if (
                    isinstance(command, dict)
                    and command.get("command") == SET_SLOT_COMMAND
                    and command.get("extractor") == SetSlotExtractor.A2A_CLIENT.value
                    and "name" in command
                )
            ]
        if a2a_client_slot_commands:
            return CalmMessageProcessor._a2a_client_slot_commands_to_merge(
                parse_data.get(COMMANDS, []), a2a_client_slot_commands
            )

        return []

    def _purge_stale_user_flow_frames(
        self, tracker: DialogueStateTracker, flows: FlowsList
    ) -> None:
        """Remove stack frames that reference flows no longer valid in the model.

        A flow is considered stale if it has been removed from the model or if its
        definition has changed (detected via fingerprint comparison against the
        hashes stored in FLOW_HASHES_SLOT). A historical DialogueStackUpdated event
        may have rehydrated a UserFlowStackFrame for such a flow. Each stale
        UserFlowStackFrame is replaced with a single CodeChangeFlowStackFrame
        (multiple stale frames still produce only one marker). Non-user-flow
        frames in the stale zone are dropped; only INTERRUPT user frames above
        a stale one are preserved so they can complete before pattern_code_change
        notifies the user. CALL frames above are dropped as they are sub-tasks
        of the stale flow whose result can never be used.
        """
        # An empty FlowsList means the flows_provider graph node hasn't run yet.
        if flows.is_empty():
            return

        stack = tracker.stack
        stale_ids = find_updated_flows(tracker, flows)
        if not stale_ids:
            return

        # Replace stale frames with CodeChangeFlowStackFrame. Only INTERRUPT frames
        # above a stale zone are kept; others are dropped because they are
        # sub-tasks of the stale flow whose result can never be used.
        clean_frames: List[BaseFlowStackFrame] = []
        code_change_inserted = False
        in_stale_zone = False
        for frame in stack.frames:
            if isinstance(frame, UserFlowStackFrame):
                if frame.flow_id in stale_ids:
                    in_stale_zone = True
                    if not code_change_inserted:
                        clean_frames.append(CodeChangeFlowStackFrame())
                        code_change_inserted = True
                else:
                    if (
                        not in_stale_zone
                        or frame.frame_type == FlowStackFrameType.INTERRUPT
                    ):
                        in_stale_zone = False
                        clean_frames.append(frame)
            elif not in_stale_zone:
                clean_frames.append(frame)

        structlogger.warning(
            "processor.stale_flow_frames_removed",
            stale_flow_ids=list(stale_ids),
            event_info=(
                "The dialogue stack contains frames for flows that no longer exist "
                "or have been modified in the model. This can happen when a flow is "
                "removed or its steps are changed after historical events were "
                "recorded for a sender. The stale frames will be removed before "
                "processing continues. "
            ),
        )
        tracker.update_stack(DialogueStack(frames=clean_frames))

    @staticmethod
    def _is_user_handoff_action(action_name: str) -> bool:
        """Test if the action hands control back to the user, ending a bot turn.

        Args:
            action_name: Name of the executed action.

        Returns:
            `True` if the action explicitly returns control to the user.
        """
        return action_name in (
            ACTION_LISTEN_NAME,
            ACTION_AGENT_REQUEST_USER_INPUT_NAME,
            ACTION_AGENT_SEND_TEXT_UPDATE,
        )

    @staticmethod
    def should_predict_another_action(action_name: str) -> bool:
        """Determine whether the processor should predict another action.

        Args:
            action_name: Name of the latest executed action.

        Returns:
            `False` if `action_name` hands control back to the user
            (`ACTION_LISTEN_NAME` or `ACTION_AGENT_REQUEST_USER_INPUT_NAME`)
            or is `ACTION_SESSION_START_NAME` (a system initialisation event, not a
            conversational turn handoff), otherwise `True`.
        """
        return (
            not CalmMessageProcessor._is_user_handoff_action(action_name)
            and action_name != ACTION_SESSION_START_NAME
        )

    async def execute_side_effects(
        self,
        events: List[Event],
        tracker: DialogueStateTracker,
        output_channel: Optional[OutputChannel],
    ) -> None:
        """Attach tracker, send bot messages, schedule and cancel reminders."""
        if output_channel:
            output_channel.attach_tracker_state(tracker)
        delivery_result = await self._send_bot_messages(events, tracker, output_channel)
        if delivery_result.events:
            tracker.update_with_events(delivery_result.events)
        await self._schedule_reminders(events, tracker, output_channel)
        await self._cancel_reminders(events, tracker)
        await self._handle_session_timer_events(events, tracker)

    async def _schedule_reminders(
        self,
        events: List[Event],
        tracker: DialogueStateTracker,
        output_channel: OutputChannel,
    ) -> None:
        """Uses the scheduler to time a job to trigger the passed reminder.

        Reminders with the same `id` property will overwrite one another
        (i.e. only one of them will eventually run).
        """
        for e in events:
            if not isinstance(e, ReminderScheduled):
                continue

            (await jobs.scheduler()).add_job(
                self.handle_reminder,
                "date",
                run_date=e.trigger_date_time,
                args=[e, tracker.sender_id, output_channel],
                id=e.name,
                replace_existing=True,
                name=e.scheduled_job_name(tracker.sender_id),
            )

    @staticmethod
    async def _cancel_reminders(
        events: List[Event], tracker: DialogueStateTracker
    ) -> None:
        """Cancel reminders that match the `ReminderCancelled` event."""
        # All Reminders specified by ReminderCancelled events will be cancelled
        for event in events:
            if isinstance(event, ReminderCancelled):
                scheduler = await jobs.scheduler()
                for scheduled_job in scheduler.get_jobs():
                    if event.cancels_job_with_name(
                        scheduled_job.name, tracker.sender_id
                    ):
                        scheduler.remove_job(scheduled_job.id)

    async def _add_flows_to_metadata(self) -> Dict[str, Any]:
        """Convert the flows to metadata."""
        flows = await self.get_flows()
        flows_metadata = {}
        for flow in flows.underlying_flows:
            flow_as_json = flow.as_json()
            flow_as_json.pop("id")
            flows_metadata[flow.id] = flow_as_json

        return {"all_flows": flows_metadata}

    async def _run_action(
        self,
        action: rasa.core.actions.action.Action,
        tracker: DialogueStateTracker,
        output_channel: OutputChannel,
        nlg: NaturalLanguageGenerator,
        prediction: PolicyPrediction,
    ) -> bool:
        # Gracefully handle actions on terminated conversations
        if tracker.terminated:
            structlogger.warning(
                "rasa.core.processor._run_action.terminated_conversation",
                event_info=(
                    "Skipping action as conversation was "
                    "terminated with a SessionEnded event."
                ),
                sender_id=tracker.sender_id,
                action_name=action.name(),
            )
            return False

        # events and return values are used to update
        # the tracker state after an action has been taken
        try:
            validate_frames: List[ValidateSlotPatternFlowStackFrame] = []
            # check if the last action was a correction action
            # before validating the corrected slots
            if tracker.latest_action_name == ACTION_CORRECT_FLOW_SLOT:
                tracker, validate_frames = self.validate_corrected_slots(tracker)

            # Use temporary tracker as we might need to discard the policy events in
            # case of a rejection.
            temporary_tracker = tracker.copy()
            temporary_tracker.update_with_events(prediction.events)

            run_args = inspect.getfullargspec(action.run).args
            extra_kwargs: Dict[str, Any] = {}

            if "metadata" in run_args:
                metadata: Optional[Dict] = prediction.action_metadata

                if isinstance(action, FormAction):
                    flows_metadata = await self._add_flows_to_metadata()
                    flows_metadata[KEY_IS_CALM_SYSTEM] = self.message_contains_commands(
                        temporary_tracker.latest_message
                    )
                    flows_metadata[KEY_IS_COEXISTENCE_ASSISTANT] = (
                        self._is_coexistence_assistant(temporary_tracker)
                    )
                    metadata = prediction.action_metadata or {}
                    metadata.update(flows_metadata)

                extra_kwargs["metadata"] = metadata

            if "flows" in run_args:
                extra_kwargs["flows"] = await self.get_flows()

            events = await action.run(
                output_channel,
                nlg,
                temporary_tracker,
                self.domain,
                **extra_kwargs,
            )

            if validate_frames:
                stack = tracker.stack
                for frame in validate_frames:
                    stack.push(frame)
                new_events = tracker.create_stack_updated_events(stack)
                tracker.update_with_events(new_events)

            self._log_action_and_events_on_tracker(tracker, action, events, prediction)
        except ActionExecutionRejection:
            events = [
                ActionExecutionRejected(
                    action.name(), prediction.policy_name, prediction.max_confidence
                )
            ]
            tracker.update(events[0])
            return self.should_predict_another_action(action.name())
        except Exception as exc:
            structlogger.exception(
                "rasa.core.processor.run_action.exception",
                event_info=f"Encountered an exception while "
                f"running action '{action.name()}'."
                f"Bot will continue, but the actions events are lost. "
                f"Please check the logs of your action server for "
                f"more information.",
            )
            error_message = str(exc)
            events, tracker = self._get_events_from_action_execution_failure(tracker)
            self._log_action_prediction_on_tracker(
                tracker,
                action,
                prediction,
                was_successful=False,
                error_message=error_message,
            )

        if any(isinstance(e, UserUttered) for e in events):
            structlogger.debug(
                "rasa.core.processor.run_action",
                message="A `UserUttered` event was returned by executing "
                f"action '{action.name()}'. This will run the default action "
                f"'{ACTION_EXTRACT_SLOTS}'.",
            )
            tracker = await self.run_action_extract_slots(output_channel, tracker)

        if action.name() != ACTION_LISTEN_NAME and not action.name().startswith(
            UTTER_PREFIX
        ):
            self._log_slots(tracker)

        hook_results = plugin_manager().hook.after_action_executed(tracker=tracker)
        awaitables = [result for result in hook_results if inspect.isawaitable(result)]
        if awaitables:
            hook_errors = await asyncio.gather(*awaitables, return_exceptions=True)
            for index, hook_error in enumerate(hook_errors):
                if isinstance(hook_error, Exception):
                    structlogger.exception(
                        "rasa.core.processor.after_action_executed.exception",
                        event_info=(
                            "Encountered an exception while running an "
                            "`after_action_executed` hook callback."
                        ),
                        action_name=action.name(),
                        hook_result_index=index,
                        error=hook_error,
                    )
        await self.execute_side_effects(events, tracker, output_channel)
        return self.should_predict_another_action(action.name())

    def _get_events_from_action_execution_failure(
        self, tracker: DialogueStateTracker
    ) -> Tuple[List[Event], DialogueStateTracker]:
        if not self.is_calm_assistant or (
            tracker.has_coexistence_routing_slot
            and not tracker.get_slot(ROUTE_TO_CALM_SLOT)
        ):
            return [], tracker

        # In CALM assistants or CALM mode, we want to trigger
        # pattern_internal_error when an action fails
        structlogger.debug(
            "rasa.core.processor.run_action.trigger_pattern_internal_error",
            event_info="Triggering pattern_internal_error "
            "due to action execution failure.",
        )

        dialogue_stack = tracker.stack
        top_frame = dialogue_stack.top()

        flow_name = (
            top_frame.flow_id if isinstance(top_frame, BaseFlowStackFrame) else ""
        )
        rasa.core.utils.cancel_flow_and_push_internal_error(dialogue_stack, flow_name)

        events = tracker.create_stack_updated_events(dialogue_stack)
        tracker.update_with_events(events)
        return events, tracker

    # ------------------------------------------------------------------
    # Turn latency: engine timing + ``BotTurnEnded`` emission.
    # Breakdown assembly lives in ``rasa.core.turn_latency``.
    # ------------------------------------------------------------------

    def _compute_execution_times_ms(self) -> Optional[Dict[str, float]]:
        """Return per-turn timing (ms) if turn timestamps are available.

        ``command_processor`` spans from turn start until the command processor
        finished. ``prediction_loop`` spans from then until *now* (caller
        context), so values on ``BotUttered`` events are cumulative up to the
        moment each batch of bot events is logged, while ``action_listen`` uses
        the value at the end of the prediction loop.

        ``rasa_processing_ms`` is the sum of the two. On ``BotUttered`` it is a
        cumulative snapshot up to that action's execution; on ``BotTurnEnded`` it
        is the final server-side turn duration. Neither value includes channel-side
        wall-clock such as TTS, pacing, or network.
        """
        if not hasattr(self, "time_turn_start"):
            return None
        if not hasattr(self, "time_command_processor"):
            return None
        execution_time_prediction_loop = (
            time.time() - self.time_command_processor
        ) * 1000
        execution_time_command_processor = (
            self.time_command_processor - self.time_turn_start
        ) * 1000
        return {
            "command_processor": execution_time_command_processor,
            "prediction_loop": execution_time_prediction_loop,
            "rasa_processing_ms": (
                execution_time_command_processor + execution_time_prediction_loop
            ),
        }

    def _emit_bot_turn_ended(self, tracker: DialogueStateTracker) -> None:
        """Append ``BotTurnEnded`` with v1 per-turn timing and latency metadata."""
        execution_times = self._compute_execution_times_ms()
        structlogger.debug(
            "processor.bot_turn_ended.emit",
            sender_id=tracker.sender_id,
            latest_action_name=tracker.latest_action_name,
            execution_times=execution_times,
        )
        metadata: Dict[str, Any] = {}
        if execution_times:
            metadata["execution_times"] = execution_times

        latency_breakdown = turn_latency.build_calm_v1_latency_breakdown(
            tracker.get_last_turn_events(), execution_times
        ).model_dump(exclude_none=True)
        if latency_breakdown:
            metadata["latency_breakdown"] = latency_breakdown

        tracker.update(BotTurnEnded(metadata=metadata))

    def _attach_execution_times_to_action_listen(
        self, action: Action, prediction: PolicyPrediction
    ) -> None:
        """Adds execution times to the ActionExecuted event metadata."""
        if not action.name() == ACTION_LISTEN_NAME:
            return

        execution_times = self._compute_execution_times_ms()
        if execution_times is None:
            return

        if prediction.action_metadata is None:
            prediction.action_metadata = {}

        prediction.action_metadata[ACTION_METADATA_EXECUTION_TIME] = execution_times

    def _attach_execution_times_to_bot_events(self, events: List[Event]) -> None:
        """Merge turn execution times into ``BotUttered`` metadata when absent."""
        bot_events = [e for e in events if isinstance(e, BotUttered)]
        if not bot_events:
            return

        execution_times = self._compute_execution_times_ms()
        for event in bot_events:
            if ACTION_METADATA_EXECUTION_TIME in event.metadata:
                continue
            if execution_times is None:
                continue
            event.metadata[ACTION_METADATA_EXECUTION_TIME] = execution_times

        structlogger.debug(
            "processor.bot_uttered.execution_times",
            bot_events_count=len(bot_events),
            execution_times=execution_times,
        )

    def _log_action_and_events_on_tracker(
        self,
        tracker: DialogueStateTracker,
        action: Action,
        events: Optional[List[Event]],
        prediction: PolicyPrediction,
    ) -> None:
        # Ensures that the code still works even if a lazy programmer missed
        # to type `return []` at the end of an action or the run method
        # returns `None` for some other reason.
        if events is None:
            events = []

        action_was_rejected_manually = any(
            isinstance(event, ActionExecutionRejected) for event in events
        )
        if not action_was_rejected_manually:
            self._log_action_prediction_on_tracker(
                tracker, action, prediction, was_successful=True, error_message=None
            )

        structlogger.debug(
            "processor.actions.log",
            action_name=action.name(),
            len_rasa_events=len(events),
        )
        self._attach_execution_times_to_bot_events(events)
        tracker.update_with_events(events)

        if (
            action.name() == ACTION_SESSION_START_NAME
            and not action_was_rejected_manually
        ):
            tracker.mark_session_start_executed_this_turn()

    def _log_action_prediction_on_tracker(
        self,
        tracker: DialogueStateTracker,
        action: Action,
        prediction: PolicyPrediction,
        was_successful: bool,
        error_message: Optional[str],
    ) -> None:
        structlogger.debug(
            "processor.actions.policy_prediction",
            prediction_event_count=len(prediction.events),
            policy_name=prediction.policy_name,
            action_name=action.name(),
        )
        tracker.update_with_events(prediction.events)

        # log the action and its produced events
        self._attach_execution_times_to_action_listen(action, prediction)
        tracker.update(
            action.event_for_successful_execution(
                prediction, was_successful, error_message
            )
        )

    def validate_corrected_slots(
        self,
        tracker: DialogueStateTracker,
    ) -> Tuple[DialogueStateTracker, List[ValidateSlotPatternFlowStackFrame]]:
        """Validate the slots that were corrected in the tracker."""
        prior_tracker_events = list(reversed(tracker.events))
        tracker, validate_frames = create_validate_frames_from_slot_set_events(
            tracker,
            prior_tracker_events,
            should_break=True,
        )

        return tracker, validate_frames

    async def _run_engine_turn(
        self,
        message: UserMessage,
        tracker: DialogueStateTracker,
    ) -> DialogueStateTracker:
        """Run one dialogue-engine turn and return the (possibly updated) tracker.

        The base (CALM v1 / NLU) engine runs the slot-extraction action followed by
        the policy prediction loop. The Mantle processor overrides this to run its
        orchestrator turn instead.
        """
        tracker = await self.run_action_extract_slots(message.output_channel, tracker)
        cancellation_token = self._active_cancellation_tokens.get(message.sender_id)
        await self.run_prediction_loop(
            message.output_channel, tracker, cancellation_token
        )
        return tracker

    async def run_action_extract_slots(
        self,
        output_channel: OutputChannel,
        tracker: DialogueStateTracker,
    ) -> DialogueStateTracker:
        """Run action to extract slots and update the tracker accordingly.

        Args:
            output_channel: Output channel associated with the incoming user message.
            tracker: A tracker representing a conversation state.

        Returns:
            the given (updated) tracker
        """
        action_extract_slots = rasa.core.actions.action.action_for_name_or_text(
            ACTION_EXTRACT_SLOTS, self.domain, self.action_endpoint
        )
        metadata = await self._add_flows_to_metadata()
        metadata[KEY_IS_CALM_SYSTEM] = self.message_contains_commands(
            tracker.latest_message
        )
        metadata[KEY_IS_COEXISTENCE_ASSISTANT] = self._is_coexistence_assistant(tracker)

        extraction_events = await action_extract_slots.run(
            output_channel, self.nlg, tracker, self.domain, metadata
        )

        delivery_result = await self._send_bot_messages(
            extraction_events, tracker, output_channel
        )

        tracker.update_with_events(extraction_events)
        if delivery_result.events:
            tracker.update_with_events(delivery_result.events)

        structlogger.debug(
            "processor.extract.slots",
            action_extract_slot=ACTION_EXTRACT_SLOTS,
            len_extraction_events=len(extraction_events),
        )

        return tracker

    async def predict_next_for_sender_id(
        self, sender_id: str
    ) -> Optional[Dict[str, Any]]:
        """Predict the next action for the given sender_id.

        Args:
            sender_id: Conversation ID.

        Returns:
            The prediction for the next action. `None` if no domain or policies loaded.
        """
        tracker = await self.fetch_tracker_and_update_session(sender_id)
        result = await self.predict_next_with_tracker(tracker)

        # save tracker state to continue conversation from this state
        await self.save_tracker(tracker)

        return result

    async def predict_next_with_tracker(
        self,
        tracker: DialogueStateTracker,
        verbosity: EventVerbosity = EventVerbosity.AFTER_RESTART,
    ) -> Optional[Dict[str, Any]]:
        """Predict the next action for a given conversation state.

        Args:
            tracker: A tracker representing a conversation state.
            verbosity: Verbosity for the returned conversation state.

        Returns:
            The prediction for the next action. `None` if no domain or policies loaded.
        """
        if self.model_metadata.training_type == TrainingType.NLU:
            rasa.shared.utils.io.raise_warning(
                "No core model. Skipping action prediction and execution.",
                docs=DOCS_URL_NLU_BASED_POLICIES,
            )
            return None

        self._purge_stale_user_flow_frames(tracker, await self.get_flows())
        prediction = await self._predict_next_with_tracker(tracker)

        scores = [
            {"action": a, "score": p}
            for a, p in zip(self.domain.action_names_or_texts, prediction.probabilities)
        ]
        return {
            "scores": scores,
            "policy": prediction.policy_name,
            "confidence": prediction.max_confidence,
            "tracker": tracker.current_state(verbosity),
        }

    async def execute_action(
        self,
        sender_id: str,
        action_name: str,
        output_channel: OutputChannel,
        nlg: NaturalLanguageGenerator,
        prediction: PolicyPrediction,
    ) -> Optional[DialogueStateTracker]:
        """Execute an action for a conversation.

        Note that this might lead to unexpected bot behavior. Rather use an intent
        to execute certain behavior within a conversation (e.g. by using
        `trigger_external_user_uttered`).

        Args:
            sender_id: The ID of the conversation.
            action_name: The name of the action which should be executed.
            output_channel: The output channel which should be used for bot responses.
            nlg: The response generator.
            prediction: The prediction for the action.

        Returns:
            The new conversation state. Note that the new state is also persisted.
        """
        # we have a Tracker instance for each user
        # which maintains conversation state
        tracker = await self.fetch_tracker_and_update_session(sender_id, output_channel)

        action = self._get_action(action_name)
        await self._run_action(action, tracker, output_channel, nlg, prediction)

        # save tracker state to continue conversation from this state
        await self.save_tracker(tracker)

        return tracker

    async def predict_next_with_tracker_if_should(
        self,
        tracker: DialogueStateTracker,
        output_channel: Optional[OutputChannel] = None,
        cancellation_token: Optional["CancellationToken"] = None,
    ) -> Tuple[rasa.core.actions.action.Action, PolicyPrediction]:
        """Predicts the next action the bot should take after seeing x.

        This should be overwritten by more advanced policies to use
        ML to predict the action.

        Returns:
             The index of the next action and prediction of the policy.

        Raises:
            ActionLimitReached if the limit of actions to predict has been reached.
        """
        should_predict_another_action = self.should_predict_another_action(
            tracker.latest_action_name
        )

        if self.is_action_limit_reached(tracker, should_predict_another_action):
            raise ActionLimitReached(
                "The limit of actions to predict has been reached."
            )

        prediction = await self._predict_next_with_tracker(
            tracker, output_channel, cancellation_token
        )

        action = rasa.core.actions.action.action_for_index(
            prediction.max_confidence_index, self.domain, self.action_endpoint
        )

        structlogger.debug(
            "rasa.core.processor.predict_next_with_tracker_if_should",
            event_info="Predicted next action.",
            action=action.name(),
            confidence=prediction.max_confidence,
        )

        return action, prediction

    @staticmethod
    def _is_reminder(e: Event, name: str) -> bool:
        return isinstance(e, ReminderScheduled) and e.name == name

    @staticmethod
    def _is_reminder_still_valid(
        tracker: DialogueStateTracker, reminder_event: ReminderScheduled
    ) -> bool:
        """Check if the conversation has been restarted after reminder."""
        for e in reversed(tracker.applied_events()):
            if CalmMessageProcessor._is_reminder(e, reminder_event.name):
                return True
        return False  # not found in applied events --> has been restarted

    @staticmethod
    def _has_message_after_reminder(
        tracker: DialogueStateTracker, reminder_event: ReminderScheduled
    ) -> bool:
        """Check if the user sent a message after the reminder."""
        for e in reversed(tracker.events):
            if CalmMessageProcessor._is_reminder(e, reminder_event.name):
                return False

            if isinstance(e, UserUttered) and e.text:
                return True

        return True  # tracker has probably been restarted

    async def handle_reminder(
        self,
        reminder_event: ReminderScheduled,
        sender_id: str,
        output_channel: OutputChannel,
    ) -> None:
        """Handle a reminder that is triggered asynchronously."""
        async with self.lock_store.lock(sender_id):
            tracker = await self.fetch_tracker_and_update_session(
                sender_id, output_channel
            )

            if (
                reminder_event.kill_on_user_message
                and self._has_message_after_reminder(tracker, reminder_event)
            ) or not self._is_reminder_still_valid(tracker, reminder_event):
                structlogger.debug(
                    "rasa.core.processor.handle_reminder",
                    event_info="Canceled reminder because it is outdated.",
                    reminder_event=reminder_event,
                )
            else:
                intent = reminder_event.intent
                entities: Union[List[Dict], Dict] = reminder_event.entities or {}
                await self.trigger_external_user_uttered(
                    intent, entities, tracker, output_channel
                )

    async def trigger_external_user_uttered(
        self,
        intent_name: str,
        entities: Optional[Union[List[Dict[str, Any]], Dict[str, str]]],
        tracker: DialogueStateTracker,
        output_channel: OutputChannel,
    ) -> None:
        """Triggers an external message.

        Triggers an external message (like a user message, but invisible;
        used, e.g., by a reminder or the trigger_intent endpoint).

        Args:
            intent_name: Name of the intent to be triggered.
            entities: Entities to be passed on.
            tracker: The tracker to which the event should be added.
            output_channel: The output channel.
        """
        # Gracefully handle external messages sent to terminated conversations
        if tracker.terminated:
            structlogger.warning(
                "rasa.core.processor.trigger_external_user_uttered.terminated_conversation",
                event_info=(
                    "Ignoring external user message with intent as "
                    "conversation was terminated with a SessionEnded event."
                ),
                sender_id=tracker.sender_id,
                intent_name=intent_name,
            )
            return

        if isinstance(entities, list):
            entity_list = entities
        elif isinstance(entities, dict):
            # Allow for a short-hand notation {"ent1": "val1", "ent2": "val2", ...}.
            # Useful if properties like 'start', 'end', or 'extractor' are not given,
            # e.g. for external events.
            entity_list = [
                {"entity": ent, "value": val} for ent, val in entities.items()
            ]
        elif not entities:
            entity_list = []
        else:
            rasa.shared.utils.io.raise_warning(
                f"Invalid entity specification: {entities}. Assuming no entities."
            )
            entity_list = []

        # Set the new event's input channel to the latest input channel, so
        # that we don't lose this property.
        input_channel = tracker.get_latest_input_channel()

        tracker.update(
            UserUttered.create_external(intent_name, entity_list, input_channel),
            self.domain,
        )

        tracker = await self.run_action_extract_slots(output_channel, tracker)

        await self.run_prediction_loop(output_channel, tracker)
        # save tracker state to continue conversation from this state
        await self.save_tracker(tracker)

    async def _parse_message_for_engine(
        self,
        message: UserMessage,
        tracker: Optional[DialogueStateTracker] = None,
        only_output_properties: bool = True,
    ) -> Dict[str, Any]:
        """Parse a user message into parse_data for the CALM v1 / NLU engine.

        Runs the v1 NLU parsing pipeline — the optional HTTP NLU interpreter or
        the in-graph pipeline (regex readers, graph-based NLU, command and intent
        handling) — then applies the v1-only retrieval-intent enrichment and the
        unseen-feature domain check. The Mantle processor overrides this with a
        minimal stub, since v2 parses inside its orchestrator rather than in a
        separate NLU step.
        """
        if self.http_interpreter:
            parse_data = await self.http_interpreter.parse(message)
        else:
            parse_data = await self._parse_message_with_pipeline(
                message, tracker, only_output_properties
            )

        self._update_full_retrieval_intent(parse_data)
        self._check_for_unseen_features(parse_data)
        return parse_data

    async def _parse_message_with_pipeline(
        self,
        message: UserMessage,
        tracker: Optional[DialogueStateTracker] = None,
        only_output_properties: bool = True,
    ) -> Dict[str, Any]:
        """Run the in-graph NLU parsing pipeline for the CALM v1 / NLU engine."""
        processed_message = Message({TEXT: message.text})

        all_flows = await self.get_flows()
        (
            should_force_slot_command,
            slot_name,
        ) = rasa.core.utils.should_force_slot_filling(tracker, all_flows)

        if should_force_slot_command:
            command = SetSlotCommand(
                name=slot_name,
                value=message.text,
                extractor=SetSlotExtractor.COMMAND_PAYLOAD_READER.value,
            )
            processed_message.set(COMMANDS, [command.as_dict()], add_to_output=True)
        else:
            regex_reader = create_regex_pattern_reader(message, self.domain)
            if regex_reader:
                processed_message = regex_reader.unpack_regex_message(
                    message=processed_message, domain=self.domain
                )

        # Invalid use of slash syntax, sanitize the message before passing
        # it to the graph.
        if (
            processed_message.starts_with_slash_syntax()
            and not processed_message.has_intent()
            and not processed_message.has_commands()
        ):
            message = self._sanitize_message(message)

        # Intent or commands are not explicitly present. Pass message to graph.
        if not (processed_message.has_intent() or processed_message.has_commands()):
            return await self._parse_message_with_graph(
                message, tracker, only_output_properties
            )

        # Intents or commands are present. Bypasses the standard parsing pipeline.
        return await self._parse_message_with_commands_and_intents(
            processed_message, tracker, only_output_properties
        )

    def _sanitize_message(self, message: UserMessage) -> UserMessage:
        """Sanitize user message by removing prepended slashes before the content."""
        # Regex pattern to match leading slashes and any whitespace before
        # actual content
        pattern = r"^[/\s]+"
        # Remove the matched pattern from the beginning of the message
        message.text = re.sub(pattern, "", message.text).strip()
        return message

    async def _parse_message_with_commands_and_intents(
        self,
        message: Message,
        tracker: Optional[DialogueStateTracker] = None,
        only_output_properties: bool = True,
    ) -> Dict[str, Any]:
        """Parses the message to handle commands or intent trigger."""
        parse_data: Dict[str, Any] = {
            TEXT: "",
            INTENT: {INTENT_NAME_KEY: None, PREDICTED_CONFIDENCE_KEY: 0.0},
            ENTITIES: [],
        }
        parse_data.update(
            message.as_dict(only_output_properties=only_output_properties)
        )

        commands = parse_data.get(COMMANDS, [])

        # add commands from intent payloads
        if tracker and not commands:
            nlu_adapted_commands = await self._nlu_to_commands(parse_data, tracker)
            commands += nlu_adapted_commands

            if (
                tracker.has_coexistence_routing_slot
                and tracker.get_slot(ROUTE_TO_CALM_SLOT) is None
            ):
                # If we are currently not routing to either CALM or DM1:
                # - Sticky route to CALM if there are any commands
                #   from the trigger intent parsing
                # - Sticky route to DM1 if there are no commands present
                route_to_calm_slot_value = self._determine_route_to_calm_slot_value(
                    nlu_adapted_commands
                )
                commands += [
                    SetSlotCommand(
                        ROUTE_TO_CALM_SLOT, route_to_calm_slot_value
                    ).as_dict()
                ]

        parse_data[COMMANDS] = commands
        return parse_data

    def _determine_route_to_calm_slot_value(
        self, nlu_adapted_commands: List[Dict[str, Any]]
    ) -> Optional[bool]:
        """Determines what value should be assigned to `ROUTE_TO_CALM_SLOT`.

        Returns:
            - True: If any command other than:
                - SessionStartCommand
                - SessionEndCommand
                - RestartCommand
              is present.
            - None: If only ignored system commands are present.
            - False If no commands at all.
        """
        system_commands_to_ignore = [
            SessionStartCommand.command(),
            SessionEndCommand.command(),
            RestartCommand.command(),
        ]

        # Exclude the system commands, as it doesn't originate from the user's
        # input intent and shouldn't influence the decision for setting
        # ROUTE_TO_CALM_SLOT.
        intent_triggered_commands = [
            command
            for command in nlu_adapted_commands
            if command.get("command") not in system_commands_to_ignore
        ]

        if len(intent_triggered_commands) > 0:
            # There are commands other than system commands present - route to CALM
            return True
        elif len(nlu_adapted_commands) > 0:
            # Only system command is present — defer routing decision
            return None
        else:
            # No commands at all — route to DM1
            return False

    async def _nlu_to_commands(
        self, parse_data: Dict[str, Any], tracker: DialogueStateTracker
    ) -> List[Dict[str, Any]]:
        """Converts the NLU parse data to commands using the adaptor.

        This is used if we receive intents/entities directly using `/intent{...}`
        syntax. In this case, the nlu graph is not run. Therefore, we need to
        convert the parse data to commands outside the graph.
        """
        from rasa.dialogue_understanding.generator.nlu_command_adapter import (
            NLUCommandAdapter,
        )

        message = Message(parse_data)
        commands = NLUCommandAdapter.convert_nlu_to_commands(
            message, tracker, await self.get_flows(), self.domain
        )
        add_commands_to_message_parse_data(
            message, NLUCommandAdapter.__name__, commands
        )
        parse_data[PREDICTED_COMMANDS] = message.get(PREDICTED_COMMANDS, [])

        # if there are no converted commands and parsed data contains invalid intent
        # add CannotHandleCommand as fallback
        if len(commands) == 0 and self._contains_undefined_intent(Message(parse_data)):
            structlogger.warning(
                "processor.message.nlu_to_commands.invalid_intent",
                event_info=(
                    f"No NLU commands converted and parsed data contains"
                    f"invalid intent: {parse_data[INTENT]['name']}. "
                    f"Returning CannotHandleCommand() as a fallback."
                ),
                invalid_intent=parse_data[INTENT][INTENT_NAME_KEY],
            )
            commands.append(
                CannotHandleCommand(RASA_PATTERN_CANNOT_HANDLE_INVALID_INTENT)
            )

        return [command.as_dict() for command in commands]

    def _contains_undefined_intent(self, message: Message) -> bool:
        """Checks if the message contains an undefined intent."""
        intent_name = message.get(INTENT, {}).get(INTENT_NAME_KEY)
        return intent_name is not None and intent_name not in self.domain.intents

    async def _parse_message_with_graph(
        self,
        message: UserMessage,
        tracker: Optional[DialogueStateTracker] = None,
        only_output_properties: bool = True,
    ) -> Dict[str, Any]:
        """Interprets the passed message.

        Arguments:
            message: Message to handle
            tracker: Tracker to use
            only_output_properties: If `True`, restrict the output to
                Message.only_output_properties.

        Returns:
            Parsed data extracted from the message.
        """
        results = await self.graph_runner.run(
            inputs={PLACEHOLDER_MESSAGE: [message], PLACEHOLDER_TRACKER: tracker},
            targets=[self.model_metadata.nlu_target],
        )
        parsed_messages = results[self.model_metadata.nlu_target]
        parsed_message = parsed_messages[0]
        parse_data = {
            TEXT: "",
            INTENT: {INTENT_NAME_KEY: None, PREDICTED_CONFIDENCE_KEY: 0.0},
            ENTITIES: [],
            COMMANDS: [],
        }
        parse_data.update(
            parsed_message.as_dict(only_output_properties=only_output_properties)
        )
        return parse_data

    @staticmethod
    def _should_handle_message(tracker: DialogueStateTracker) -> bool:
        if tracker.terminated:
            return False
        return not tracker.paused or CalmMessageProcessor._last_user_intent_is_restart(
            tracker
        )

    @staticmethod
    def _last_user_intent_is_restart(tracker: DialogueStateTracker) -> bool:
        """Check if the last user intent is a restart intent."""
        return (
            tracker.latest_message is not None
            and tracker.latest_message.intent.get(INTENT_NAME_KEY)
            == USER_INTENT_RESTART
        )

    def _tracker_state_specific_action_limit(
        self, tracker: DialogueStateTracker
    ) -> int:
        """Select the action limit based on the tracker state.

        This function determines the maximum number of predictions that should be
        made during a dialogue conversation. Typically, the number of predictions
        is limited to the number of actions executed so far in the conversation.
        However, in certain states (e.g., when the user is correcting the
        conversation flow), more predictions may be allowed as the system traverses
        through a long dialogue flow.

        Additionally, if the `ROUTE_TO_CALM_SLOT` is present in the tracker slots,
        the action limit is adjusted to a separate limit for CALM-based flows.

        Args:
            tracker: instance of DialogueStateTracker.

        Returns:
        The maximum number of predictions to make.
        """
        # Check if it is a CALM assistant and if so, that the `ROUTE_TO_CALM_SLOT`
        # is either not present or set to `True`.
        # If it does, use the specific prediction limit for CALM assistants.
        # Otherwise, use the default prediction limit.
        if self.is_calm_assistant and (
            not tracker.has_coexistence_routing_slot
            or tracker.get_slot(ROUTE_TO_CALM_SLOT)
        ):
            max_number_of_predictions = self.max_number_of_predictions_calm
        else:
            max_number_of_predictions = self.max_number_of_predictions

        reversed_events = list(tracker.events)[::-1]
        is_conversation_in_flow_correction = False
        for e in reversed_events:
            if isinstance(e, ActionExecuted):
                if e.action_name in (ACTION_LISTEN_NAME, ACTION_SESSION_START_NAME):
                    break
                elif e.action_name == ACTION_CORRECT_FLOW_SLOT:
                    is_conversation_in_flow_correction = True
                    break

        if is_conversation_in_flow_correction:
            # allow for more predictions to be made as we might be traversing through
            # a long flow. We multiply the number of predictions by 10 to allow for
            # more predictions to be made - the factor is a best guess.
            return max_number_of_predictions * 5

        # Return the default
        return max_number_of_predictions

    def is_action_limit_reached(
        self, tracker: DialogueStateTracker, should_predict_another_action: bool
    ) -> bool:
        """Check whether the maximum number of predictions has been met.

        Args:
            tracker: instance of DialogueStateTracker.
            should_predict_another_action: Whether the last executed action allows
            for more actions to be predicted or not.

        Returns:
            `True` if the limit of actions to predict has been reached.
        """
        reversed_events = list(tracker.events)[::-1]
        num_predicted_actions = 0
        state_specific_action_limit = self._tracker_state_specific_action_limit(tracker)

        for e in reversed_events:
            if isinstance(e, ActionExecuted):
                if e.action_name in (ACTION_LISTEN_NAME, ACTION_SESSION_START_NAME):
                    break
                num_predicted_actions += 1

        return (
            num_predicted_actions >= state_specific_action_limit
            and should_predict_another_action
        )

    async def run_prediction_loop(
        self,
        output_channel: OutputChannel,
        tracker: DialogueStateTracker,
        cancellation_token: Optional["CancellationToken"] = None,
    ) -> None:
        # keep taking actions decided by the policy until it chooses to 'listen'

        await self._purge_stale_frames_for_turn(tracker)

        tracker = await self.run_command_processor(tracker)
        self.time_command_processor = time.time()

        await self.process_tracker(output_channel, tracker, cancellation_token)

    async def process_tracker(
        self,
        output_channel: OutputChannel,
        tracker: DialogueStateTracker,
        cancellation_token: Optional["CancellationToken"] = None,
    ) -> None:
        # action loop. predicts actions until we hit action listen
        should_predict_another_action = True
        while should_predict_another_action and self._should_handle_message(tracker):
            # this actually just calls the policy's method by the same name
            try:
                action, prediction = await self.predict_next_with_tracker_if_should(
                    tracker, output_channel, cancellation_token
                )
            except ActionLimitReached:
                structlogger.warning(
                    "rasa.core.processor.run_prediction_loop",
                    event_info="Circuit breaker tripped. Stopped predicting more "
                    "actions.",
                    sender_id=tracker.sender_id,
                )
                if self.on_circuit_break:
                    # call a registered callback
                    self.on_circuit_break(tracker, output_channel, self.nlg)
                break

            if prediction.is_end_to_end_prediction:
                structlogger.debug(
                    "rasa.core.processor.run_prediction_loop",
                    event_info="An end-to-end prediction was made which has "
                    "triggered the 2nd execution of the default action.",
                    action=ACTION_EXTRACT_SLOTS,
                )
                tracker = await self.run_action_extract_slots(output_channel, tracker)

            should_predict_another_action = await self._run_action(
                action, tracker, output_channel, self.nlg, prediction
            )

        self._on_prediction_loop_ended(tracker)

    async def run_command_processor(
        self, tracker: DialogueStateTracker
    ) -> DialogueStateTracker:
        """Run the command processor to apply commands to the stack.

        The command processor applies all the commands from the NLU pipeline to the
        dialogue stack. The dialogue stack then acts as base for decision making for
        the policies that can use it.

        Args:
            tracker: the dialogue state tracker

        Returns:
        An updated tracker after commands have been applied
        """
        target = "command_processor"
        results = await self.graph_runner.run(
            inputs={PLACEHOLDER_TRACKER: tracker.copy()}, targets=[target]
        )
        events = results[target]
        tracker.update_with_events(events)
        return tracker

    async def get_flows(self) -> FlowsList:
        """Get the list of flows from the graph.

        Cached for this instance's lifetime: flows are derived from the
        loaded model's graph, which never changes without a full model
        reload (always a new processor instance).
        """
        if self._flows is None:
            target = "flows_provider"
            results = await self.graph_runner.run(inputs={}, targets=[target])
            self._flows = results[target]
        return self._flows

    async def prepare_subagents(self, sub_agents: "AvailableAgents") -> None:
        """Initialise the sub-agents declared for this assistant.

        The base (CALM v1) implementation reads the model's flows and initialises
        the configured sub-agents from them. Mantle models have an empty graph
        (no ``flows_provider`` node), so the v2 processor overrides this as a no-op.
        """
        from rasa.shared.agents.agent_setup import initialize_agents

        flows = await self.get_flows()
        await initialize_agents(flows, sub_agents)

    def _on_prediction_loop_ended(self, tracker: DialogueStateTracker) -> None:
        """Emit ``BotTurnEnded`` when the prediction loop hands control back.

        Timing metadata captured during the turn is attached to the event.
        """
        if not self._is_user_handoff_action(tracker.latest_action_name):
            structlogger.debug(
                "processor.bot_turn_ended.skipped",
                sender_id=tracker.sender_id,
                latest_action_name=tracker.latest_action_name,
                reason="latest action is not a turn-ending action",
            )
            return
        self._emit_bot_turn_ended(tracker)
        plugin_manager().hook.after_prediction_loop_end(tracker=tracker)

    async def _predict_next_with_tracker(
        self,
        tracker: DialogueStateTracker,
        output_channel: Optional[OutputChannel] = None,
        cancellation_token: Optional["CancellationToken"] = None,
    ) -> PolicyPrediction:
        """Collect predictions from ensemble and return action and predictions."""
        followup_action = tracker.followup_action
        if followup_action:
            tracker.clear_followup_action()
            if followup_action in self.domain.action_names_or_texts:
                prediction = PolicyPrediction.for_action_name(
                    self.domain, followup_action, FOLLOWUP_ACTION
                )
                return prediction

            structlogger.error(
                "rasa.core.processor.predict_next_with_tracker",
                event_info="Trying to run unknown follow-up action.",
                message=(
                    "Trying to run unknown follow-up action. Instead of running "
                    "that, Rasa Pro will ignore the action and predict the next action."
                ),
                followup_action=followup_action,
            )

        target = self.model_metadata.core_target
        if not target:
            raise ValueError("Cannot predict next action if there is no core target.")

        inputs: Dict[str, Any] = {
            PLACEHOLDER_TRACKER: tracker,
            PLACEHOLDER_ENDPOINTS: self.endpoints,
            PLACEHOLDER_OUTPUT_CHANNEL: output_channel,
            PLACEHOLDER_CANCELLATION_TOKEN: cancellation_token,
        }

        results = await self.graph_runner.run(
            inputs=inputs,
            targets=[target],
        )
        policy_prediction = results[target]
        return policy_prediction


def create_message_processor(
    model_path: Union[str, Path],
    tracker_store: rasa.core.tracker_stores.tracker_store.TrackerStore,
    lock_store: LockStore,
    generator: NaturalLanguageGenerator,
    action_endpoint: Optional[EndpointConfig] = None,
    max_number_of_predictions: int = MAX_NUMBER_OF_PREDICTIONS,
    max_number_of_predictions_calm: int = MAX_NUMBER_OF_PREDICTIONS_CALM,
    on_circuit_break: Optional[LambdaType] = None,
    http_interpreter: Optional[RasaNLUHttpInterpreter] = None,
    endpoints: Optional["AvailableEndpoints"] = None,
    privacy_manager: Optional["BackgroundPrivacyManager"] = None,
    timer_manager: Optional["SessionTimerManager"] = None,
) -> MessageProcessor:
    """Construct the right ``MessageProcessor`` subtype for the model's engine.

    The engine version is inspected exactly once here, via a cheap metadata-only
    read that does not build the graph runner. Mantle models get a
    ``MantleMessageProcessor``; everything else (CALM v1 / NLU) gets a
    ``CalmMessageProcessor``. Callers hold a ``MessageProcessor``-typed reference
    and never branch on the engine version themselves.
    """
    # Resolve the concrete archive once and reuse it for both the version probe and
    # the graph load, so the two cannot disagree if the newest archive in a models
    # directory changes between the calls.
    model_archive = BaseMessageProcessor._resolve_model_archive(model_path)
    engine_version = BaseMessageProcessor._read_engine_version(model_archive)

    processor_class: type[BaseMessageProcessor] = CalmMessageProcessor
    if engine_version == MANTLE_ENGINE_VERSION:
        from rasa.mantle.processor import MantleMessageProcessor

        processor_class = MantleMessageProcessor

    structlogger.info(
        "rasa.core.processor.create_message_processor",
        engine_version=engine_version,
        processor_class=processor_class.__name__,
    )

    return processor_class(
        model_path=model_path,
        tracker_store=tracker_store,
        lock_store=lock_store,
        generator=generator,
        action_endpoint=action_endpoint,
        max_number_of_predictions=max_number_of_predictions,
        max_number_of_predictions_calm=max_number_of_predictions_calm,
        on_circuit_break=on_circuit_break,
        http_interpreter=http_interpreter,
        endpoints=endpoints,
        privacy_manager=privacy_manager,
        timer_manager=timer_manager,
        model_archive=model_archive,
    )
